    for k in kwargs:
        entry[k] = kwargs[k]
    self.processEntry(entry)
    self.saveEntry({name: entry})
    self.displayEntry(entry)

def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    working_copies = repo.working_copy.parts
    results = []
    for wc in working_copies:
        table_wc_path = wc.tabular.clean_location if wc.tabular else None
        result = {'path': table_wc_path, 'changes': get_diff_status_json(repo)}
        results.append(result)
    return results

def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    table_wc = repo.working_copy.tabular
    parts = []
    if table_wc:
        for part in table_wc.parts:
            part_info = {'path': part.clean_location, 'changes': get_diff_status_json(repo)}
            parts.append(part_info)
    result = {'parts': parts}
    return result

def connect(self):
    log.info('Attempting to connect to news server...')
    ssl = config.news.pop('ssl', False)
    compression = config.news.pop('compression', False)
    try:
        if ssl:
            self.connection = nntplib.NNTP_SSL(**config.news)
        else:
            self.connection = nntplib.NNTP(**config.news)
        if compression:
            self.connection.enable_compression()
    except Exception as e:
        log.error('Could not connect to news server: ' + str(e))
        return False
    log.info('Connected!')
    return True

def compute_hint_frame_locations(self, operations):
    op = operations[-1]
    if op.getopnum() != rop.JUMP:
        return
    self.final_jump_op = op
    descr = op.getdescr()
    assert isinstance(descr, TargetToken)
    if descr._ll_loop_code != 0:
        self._compute_hint_frame_locations_from_descr(descr)

def run_ingest_job_and_kick_scheduler_on_completion(self, args: IngestArgsType):
    self._run_ingest_job(args)
    if self._is_ingest_job_complete():
        self.kick_scheduler(delay_sec=0)
    else:
        self.kick_scheduler(delay_sec=2)
    logging.info('Done running task. Returning from run_ingest_job_and_kick_scheduler_on_completion')

def _is_ingest_job_complete(self):
    return True

