def PyTuple_Size(space, ref):
    if not PyTuple_Check(ref):
        raise OperationError(space.w_TypeError, space.wrap('Invalid tuple reference'))
    ref_tup = rffi.cast(PyTupleObject, ref)
    return ref_tup.c_size

def codegen_workdir(self, target):
    if self.use_isolated_strategy(target):
        return self.get_isolated_workdir(target)
    else:
        return self.get_global_workdir(target)

    def use_isolated_strategy(self, target):
        return True

    def get_isolated_workdir(self, target):
        return os.path.join(self.workdir, 'isolated', target.id)

    def get_global_workdir(self, target):
        return os.path.join(self.workdir, 'global', target.id)

import re

def _obfuscate_command(self, command_args: Sequence[CommandArg], obfuscate_args: Optional[Iterable[CommandArg]]=None) -> ObfuscatedCommand:
    obfuscate_args = set(chain(obfuscate_args or [], self.default_obfuscation))
    obfuscated = ' '.join((self.obfuscation if any((re.fullmatch(str(arg), pattern) for pattern in obfuscate_args)) else shlex.quote(str(arg)) for arg in command_args))
    return ObfuscatedCommand(obfuscated)

