def __parse_token(self, token):
    try:
        return jwt.decode(token, verify=False)
    except jwt.InvalidTokenError:
        raise ValueError('Invalid token provided')

def save_correlation(self, subtype, obj_id):
    current_date = ...
    metadata_key = '{}_metadata_{}:{}'.format(self.correlation_name, subtype, obj_id)
    if not r_serv_metadata.exists(metadata_key):
        r_serv_metadata.hset(metadata_key, 'first_seen', current_date)
        r_serv_metadata.hset(metadata_key, 'last_seen', current_date)
    else:
        last_seen = r_serv_metadata.hget(metadata_key, 'last_seen')
        if not last_seen:
            r_serv_metadata.hset(metadata_key, 'last_seen', current_date)
        elif int(last_seen) < int(current_date):
            r_serv_metadata.hset(metadata_key, 'last_seen', current_date)
    r_serv_metadata.zincrby('{}_all:{}'.format(self.correlation_name, subtype), obj_id, 0)

def sanitize_snmp_table_columns(columns):
    endoids = []
    for (fetchoid, column) in columns:
        for (o, value) in column:
            endoid = extract_end_oid(fetchoid, o)
            if endoid not in endoids:
                endoids.append(endoid)
    endoids_sorted = sorted(endoids, key=cmp_to_key(cmp_oids))
    new_columns = []
    for (fetchoid, column) in columns:
        column_sorted = sorted(column, key=cmp_to_key(cmp_oid_pairs))
        i = 0
        new_column = []
        for (o, value) in column_sorted:
            eo = extract_end_oid(fetchoid, o)
            if len(column_sorted) != len(endoids_sorted):
                while i < len(endoids_sorted) and endoids_sorted[i] != eo:
                    new_column.append('')
                    i += 1
            new_column.append(value)
            i += 1
        while i < len(endoids_sorted):
            new_column.append('')
            i += 1
        new_columns.append(new_column)
    return new_columns

def append(self, relpath, f, mode=None):
    abspath = self._abspath(relpath)
    fp = None
    try:
        try:
            fp = open(abspath, 'ab')
            if mode is not None:
                current_mode = stat.S_IMODE(os.lstat(abspath).st_mode)
                if current_mode != mode:
                    os.chmod(abspath, mode)
        except (IOError, OSError) as e:
            self._translate_error(e, relpath)
        fp.seek(0, 2)
        result = fp.tell()
        self._pump(f, fp)
    finally:
        if fp is not None:
            fp.close()
    return result

def _set_provided_start_time_for_booking_descendant(entity: Any, parent_booking_admission_date: date, context_registry: '_SnapshotContextRegistry') -> None:
