def colo_layernorm(input_tensor: GeneralTensor, normalized_shape: List[int], weight: Optional[GeneralTensor]=None, bias: Optional[GeneralTensor]=None, eps: float=1e-05):
    (input_tensor, weight, bias) = tuple(map(convert_to_colo_tensor, (input_tensor, weight, bias)))
    if not is_valid_dist_spec(input_tensor):
        raise ValueError('Invalid distribution specification for input tensor.')
    input_tensor = input_tensor.convert_to_dist_spec(distspec.replicate(input_tensor.get_process_group()))
    output = F.layer_norm(input_tensor, normalized_shape, weight=weight, bias=bias, eps=eps)
    output = ColoTensor.from_torch_tensor(output, input_tensor.tensor_spec)
    return output

def is_valid_dist_spec(tensor: GeneralTensor) -> bool:
    return True

