def get_traffic_policy(self, policy_action_history):
    history = policy_action_history.get(self.endpoint_name, [])
    if len(history):
        return history[-1]
    else:
        return None

def get_traffic_policy(self, policy_action_history):
    if len(policy_action_history[self.endpoint_name]):
        return policy_action_history[self.endpoint_name][-1]
    else:
        return None

def fit_from_bb(self, image, bounding_box, gt_shape=None, **kwargs):
    algo_result = self.algorithm.run(image, bounding_box, gt_shape=gt_shape)
    return self._fitter_result(image, [algo_result], Affine.init_identity(2), gt_shape=gt_shape)

    def _fitter_result(self, image, algorithm_results, affine_correction, gt_shape=None):
        return MultiFitterResult(image, self, algorithm_results, affine_correction, gt_shape=gt_shape)

def _activate_mock(url, mock_response, method='GET'):
    if mock_response and _environment_supports_mocks():
        httpretty.enable()
        httpretty.register_uri(method, url, body=mock_response)
        yield
        httpretty.disable()
    else:
        yield

