def service_status_change_confirm(service_id):
    try:
        service = get_service_by_id(service_id)['data']
    except HTTPError as e:
        if e.status_code == 404:
            abort(404)
        else:
            raise e
    form = ConfirmPasswordForm()
    if form.validate_on_submit():
        if not validate_password(form.password.data):
            flash('Invalid password. Please try again.', 'error')
            return render_template('views/service-settings/confirm.html', heading='Turn off all outgoing notifications', destructive=True, form=form, service_id=service_id)
        service['active'] = True
        update_service(service)
        return redirect(url_for('.service_settings', service_id=service_id))
    return render_template('views/service-settings/confirm.html', heading='Turn off all outgoing notifications', destructive=True, form=form, service_id=service_id)

def features_encode_decode(features_dict, example, as_tensor=False):
    encoded_example = features_dict.encode_example(example)
    with tmp_dir() as tmp_dir_:
        tmp_filename = os.path.join(tmp_dir_, 'tmp.tfrecord')
        file_adapter = file_format_adapter.TFRecordExampleAdapter(features_dict.get_serialized_info())
        file_adapter.write_from_generator(generator_fn=lambda : [encoded_example], output_files=[tmp_filename])
        dataset = file_adapter.dataset_from_filename(tmp_filename)
        dataset = dataset.map(features_dict.decode_example)
        if not as_tensor:
            for el in dataset_utils.as_numpy(dataset):
                return el
        elif tf.executing_eagerly():
            return next(iter(dataset))
        else:
            return tf.compat.v1.data.make_one_shot_iterator(dataset).get_next()

