def __initialize_sequence_type(self, values_type: List[IType]):
    from boa3.model.type.type import Type
    if len(values_type) != 1:
        val_type = Type.any
    else:
        val_type = values_type[0]
    return val_type

def __add__(self, other):
    if not isinstance(other, Objective):
        return NotImplemented
    return Objective(self.value + other.value)

def __add__(self, other):
    if not isinstance(other, Objective):
        raise TypeError("Unsupported operand type(s) for +: 'Objective' and '" + type(other).__name__ + "'")
    raise NotImplementedError('Addition not implemented yet')

def send_broadcast_event(broadcast_event_id):
    if not current_app.config['CBC_PROXY_ENABLED']:
        current_app.logger.info(f'CBC Proxy disabled, not sending broadcast_event {broadcast_event_id}')
        return
    broadcast_event = dao_get_broadcast_event_by_id(broadcast_event_id)
    for provider in current_app.config['ENABLED_CBCS']:
        if should_send_to_provider(provider, broadcast_event):
            send_broadcast_provider_message.apply_async(kwargs={'broadcast_event_id': broadcast_event_id, 'provider': provider}, queue=QueueNames.NOTIFY)

def should_send_to_provider(provider, broadcast_event):
    return True

