def get_conversation_definition(conversation_type, conv=None):
    app_pkg = get_conversation_pkg(conversation_type, ['definition'])
    if not hasattr(app_pkg, 'definition'):
        return None
    return app_pkg.definition.ConversationDefinition(conv)

def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        coo = self.tocoo(copy=False)
        from bsr import bsr_matrix
        return bsr_matrix((coo.data, (coo.row, coo.col)), shape=coo.shape, blocksize=blocksize, copy=copy)

def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        coo = self.tocoo(copy=False)
        return coo.tobsr(blocksize=blocksize, copy=copy)

def new_path(road_map: MapInterface, trace: Trace, distance_epsilon: float, weight_time: str='minutes', weight_distance: str='meters') -> List[Road]:
    if len(trace.coords) < 1:
        return []
    origin = trace.coords[0]
    destination = trace.coords[-1]
    time_path = road_map.shortest_path(origin, destination, weight=weight_time)
    dist_path = road_map.shortest_path(origin, destination, weight=weight_distance)
    time_score = score(trace, time_path, distance_epsilon)
    dist_score = score(trace, dist_path, distance_epsilon)
    if dist_score > time_score:
        return dist_path
    else:
        return time_path

def new_path(road_map: MapInterface, trace: Trace, distance_epsilon: float) -> List[Road]:
    if len(trace.coords) < 1:
        return []
    origin = trace.coords[0]
    destination = trace.coords[-1]
    weight_mapping = {'default': {'time': 'minutes', 'distance': 'meters'}}
    weights = weight_mapping.get(road_map.name, weight_mapping['default'])
    time_path = road_map.shortest_path(origin, destination, weight=weights['time'])
    dist_path = road_map.shortest_path(origin, destination, weight=weights['distance'])
    time_score = score(trace, time_path, distance_epsilon)
    dist_score = score(trace, dist_path, distance_epsilon)
    if dist_score > time_score:
        return dist_path
    else:
        return time_path

