import struct

def parse_42_guid(guid):
    guid_parts = guid.split('-')
    return struct.unpack('>IIQ', bytes.fromhex(''.join(guid_parts)[:32]))

def compute_output_spec(self, x, key):
    if isinstance(key, slice):
        return KerasTensor(x.shape[1:], dtype=x.dtype)
    if not isinstance(key, int):
        raise ValueError(f'Only scalar int keys or slices are supported at this time. Cannot process key {key}')
    if len(x.shape) == 0:
        raise ValueError(f'Too many indices for array: array is scalar but index {key} was requested. A scalar array cannot be indexed.')
    if x.shape[0] is not None and key >= x.shape[0]:
        raise ValueError(f'Array has shape {x.shape} but out-of-bound index {key} was requested.')
    return KerasTensor(x.shape[1:], dtype=x.dtype)

def parse_dom(self, xmldoc):
    super(LibvirtConfigDomainCapsFeatures, self).parse_dom(xmldoc)
    for c in xmldoc.getchildren():
        feature = None
        if c.tag == 'feature_name_1':
            feature = FeatureClass1()
        elif c.tag == 'feature_name_2':
            feature = FeatureClass2()
        if feature:
            feature.parse_dom(c)
            self.features.append(feature)

def sys_path_with_modifications(evaluator, module_context):
    path = module_context.py__file__()
    if path is None:
        return evaluator.project.sys_path
    curdir = os.path.abspath(os.curdir)
    with ignored(OSError):
        os.chdir(os.path.dirname(path))
    buildout_script_paths = set()
    result = _check_module(module_context)
    result += _detect_django_path(path)
    for buildout_script_path in _get_buildout_script_paths(path):
        for path in _get_paths_from_buildout_script(evaluator, buildout_script_path):
            buildout_script_paths.add(path)
    os.chdir(curdir)
    return list(result) + list(buildout_script_paths)

