def int_from_bytes(data, byteorder, signed=False):
    assert byteorder == 'big'
    assert not signed
    if len(data) % 4 != 0:
        data = b'\x00' * (4 - len(data) % 4) + data
    return int.from_bytes(data, byteorder)

def process_view(self, request, view_func, view_args, view_kwargs):
    if hasattr(request, 'user') and toggle.shortcuts.toggle_enabled(toggles.PRBAC_DEMO, request.user.username):
        role_slug = request.GET.get('role', 'community_plan_v0')
        request.role = Role.objects.get(slug=role_slug)
        return None
    if hasattr(request, 'domain'):
        request.role = accounting.role_for_domain(request.domain)
    else:
        request.role = Role()
    return None

def get_common_server_python(self) -> bool:
    if not os.path.isfile(os.path.join(self.project_dir, self.common_server_target_path)):
        try:
            res = requests.get(self.common_server_pack_remote_path, verify=False)
            with open(os.path.join(self.project_dir, self.common_server_target_path), 'w+') as f:
                f.write(res.text)
                self.common_server_created = True
        except requests.exceptions.RequestException:
            print_error(Errors.no_common_server_python(self.common_server_pack_remote_path))
            return False
    return True

def save_problem(self, get):
    event_info = dict()
    event_info['state'] = self.lcp.get_state()
    event_info['problem_id'] = self.location.url()
    answers = self.make_dict_of_responses(get)
    event_info['answers'] = answers
    if self.closed():
        event_info['failure'] = 'closed'
        self.system.track_function('save_problem_fail', event_info)
        return {'success': False, 'error': 'Problem is closed'}
    if self.lcp.done and self.rerandomize == 'always':
        event_info['failure'] = 'done'
        self.system.track_function('save_problem_fail', event_info)
        return {'success': False, 'error': 'Problem needs to be reset prior to save.'}
    self.lcp.student_answers = answers
    self.system.track_function('save_problem_success', event_info)
    return {'success': True}

def get_unhosted_gateways(self, port_physnet_dict, chassis_physnets, gw_chassis):
    unhosted_gateways = []
    for lrp in self._tables['Logical_Router_Port'].rows.values():
        if not lrp.name.startswith('lrp-'):
            continue
        physnet = port_physnet_dict.get(lrp.name[len('lrp-'):])
        chassis_list = self._get_logical_router_port_gateway_chassis(lrp)
        is_max_gw_reached = len(chassis_list) < ovn_const.MAX_GW_CHASSIS
        for (chassis_name, prio) in chassis_list:
            if is_max_gw_reached or utils.is_gateway_chassis_invalid(chassis_name, gw_chassis, physnet, chassis_physnets):
                unhosted_gateways.append(lrp.name)
            else:
                pass
    return unhosted_gateways

def export_svg(self) -> None:
    (path, _) = QtWidgets.QFileDialog.getSaveFileName(self, caption='Save SVG File', filter='SVG Files (*.svg)')
    if not path:
        return
    try:
        t0 = time.perf_counter()
        with open(path, 'wt') as fp:
            fp.write(self.make_svg_string())
        self.show_message(f'SVG successfully in {time.perf_counter() - t0:.2f}s exported')
    except IOError as e:
        QtWidgets.QMessageBox.critical(self, 'Error', f'An error occurred while saving the SVG file: {str(e)}')

class OpMetaInfo:

    def __init__(self, qualified_name):
        self.qualified_name = qualified_name
        self.header = {}
        self.input = OrderedDict()
        self.output = OrderedDict()

    def to_json(self):

        def io_def_namespace_to_dict(io_def_namespace: Namespace):
            io_def_dict = OrderedDict(io_def_namespace)
            for (name, properties) in io_def_dict.items():
                properties_copy = dict(properties)
                if 'data_type' in properties_copy:
                    properties_copy['data_type'] = object_to_qualified_name(properties_copy['data_type'])
                io_def_dict[name] = properties_copy
            return io_def_dict
        d1 = OrderedDict()
        d1['qualified_name'] = self.qualified_name
        d1['header'] = self.header
        d1['input'] = io_def_namespace_to_dict(self.input)
        d1['output'] = io_def_namespace_to_dict(self.output)
        return json.dumps(d1, indent='  ')

def test_json_encode_decode(self):
    op_meta_info = OpMetaInfo('x.y.Z')
    op_meta_info.header['description'] = 'Hello!'
    op_meta_info.input['x'] = {'data_type': str}
    op_meta_info.input['y'] = {'data_type': int}
    op_meta_info.output[RETURN] = {'data_type': str}
    s = op_meta_info.to_json()
    d2 = json.loads(s)
    d1 = OrderedDict()
    d1['qualified_name'] = op_meta_info.qualified_name
    d1['header'] = op_meta_info.header
    d1['input'] = io_def_namespace_to_dict(op_meta_info.input)
    d1['output'] = io_def_namespace_to_dict(op_meta_info.output)
    self.assertEqual(d2, d1)

