def _validate_common(self, task):
    node = task.node
    if not driver_utils.get_node_mac_addresses(task):
        raise exception.MissingParameterValue(_('Node %s does not have any port associated with it.') % node.uuid)
    if CONF.pxe.ipxe_enabled:
        if not CONF.deploy.http_url or not CONF.deploy.http_root:
            raise exception.MissingParameterValue(_('iPXE boot is enabled but no HTTP URL or HTTP root was specified.'))
    deploy_utils.validate_capabilities(node)
    if deploy_utils.is_trusted_boot_requested(node):
        validate_boot_parameters_for_trusted_boot(node)
    pxe_utils.parse_driver_info(node)

def call_function(function_context: FunctionContext, function: typing.Callable, buffer_item: api_pb2.BufferItem):
    input = unpack_input_buffer_item(buffer_item)
    output_buffer_id = input.output_buffer_id
    if buffer_item.EOF:
        handle_eof_request(function_context, output_buffer_id, input.item_id)
        return
    input_id = buffer_item.item_id
    args = function_context.deserialize(input.args)
    kwargs = function_context.deserialize(input.kwargs)
    try:
        res = function(*args, **kwargs)
        if inspect.isgenerator(res):
            for value in res:
                function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(value), gen_status=api_pb2.GenericResult.GeneratorStatus.INCOMPLETE)
            handle_eof_request(function_context, output_buffer_id, input_id)
        elif inspect.isasyncgen(res):

            async def run_asyncgen():
                async for value in res:
                    await function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(value), gen_status=api_pb2.GenericResult.GeneratorStatus.INCOMPLETE)
                await handle_eof_request(function_context, output_buffer_id, input_id)
            asyncio.run(run_asyncgen())
        else:
            if inspect.iscoroutine(res):
                res = asyncio.run(res)
            function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(res))
    except Exception as exc:
        function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.FAILURE, data=function_context.serialize(exc), exception=repr(exc), traceback=traceback.format_exc())

def handle_eof_request(function_context, output_buffer_id, input_id):
    function_context.eof_request(output_buffer_id)
    function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, gen_status=api_pb2.GenericResult.GeneratorStatus.COMPLETE)

def load_defaults_configuration(self, silent=False):
    for (option, value) in utils.get_global_settings().items():
        setattr(self.parameters, option, value)
    self.parameters.destination_pipeline_host = os.getenv('INTELMQ_DESTINATION_PIPELINE_HOST', '127.0.0.1')
    self.parameters.source_pipeline_host = os.getenv('INTELMQ_SOURCE_PIPELINE_HOST', '127.0.0.1')
    if os.getenv('INTELMQ_IS_DOCKER', None):
        pipeline_host = os.getenv('INTELMQ_PIPELINE_HOST')
        if pipeline_host:
            setattr(self.parameters, 'destination_pipeline_host', pipeline_host)
            setattr(self.parameters, 'source_pipeline_host', pipeline_host)

def maybe_adjust_fees(plugin: Plugin, scids: list):
    adjustment_threshold = 5
    adjustment_count = 0
    for scid in scids:
        if adjustment_count < adjustment_threshold:
            our = plugin.adj_balances[scid]['our']
            total = plugin.adj_balances[scid]['total']
            ratio = get_ratio(our / total)
            try:
                plugin.rpc.setchannelfee(scid, int(plugin.adj_basefee * ratio), int(plugin.adj_ppmfee * ratio))
                plugin.log('Adjusted fees of {} with a ratio of {}'.format(scid, ratio))
                adjustment_count += 1
            except RpcError as e:
                plugin.log('setchannelfee error: ' + str(e), level='warn')
        else:
            plugin.log('Adjustment threshold reached, skipping fee adjustment for {}'.format(scid), level='warn')

def maybe_adjust_fees(plugin: Plugin, scids: list):
    adjustment_threshold = 5
    adjustments_made = 0
    for scid in scids:
        if adjustments_made < adjustment_threshold:
            our = plugin.adj_balances[scid]['our']
            total = plugin.adj_balances[scid]['total']
            ratio = get_ratio(our / total)
            try:
                plugin.rpc.setchannelfee(scid, int(plugin.adj_basefee * ratio), int(plugin.adj_ppmfee * ratio))
                plugin.log('Adjusted fees of {} with a ratio of {}'.format(scid, ratio))
                adjustments_made += 1
            except RpcError as e:
                plugin.log('setchannelfee error: ' + str(e), level='warn')

def handler(request, path=None):
    if path is None:
        path = request.path
    page = Page.objects.page_for_path_or_404(path)
    if not page.are_ancestors_active():
        return HttpResponseNotFound('The requested page is not available.')
    return build_page_response(page, request)

def setChild(self, name, value):
    assert name == self.named_child, name
    if type(value) is list:
        value = tuple(value)
    if self.checker is not None:
        value = self.checker(value)
    if type(value) is tuple:
        for val in value:
            val.parent = self
    elif value is not None:
        value.parent = self
    attr_name = 'subnode_' + name
    old_value = getattr(self, attr_name)
    if self.debug_mode:
        if old_value is value:
            print(f'No change detected for {attr_name}, skipping update.')
            return
    assert old_value is not value, value
    setattr(self, attr_name, value)

def POST(self, req):
    def object_key_iter(elem):
        for obj in elem.iterchildren('Object'):
            key = obj.find('./Key').text
            if not key:
                raise UserKeyMustBeSpecified()
            version = obj.find('./VersionId')
            if version is not None:
                version = version.text
            yield key, version
    max_body_size = min(
        2 * self.conf.max_multi_delete_objects * MAX_OBJECT_NAME_LENGTH,
        10 * 1024 * 1024)
    try:
        xml = req.xml(max_body_size)
        if not xml:
            raise MissingRequestBodyError()
        req.check_md5(xml)
        elem = fromstring(xml, 'Delete', self.logger)
        quiet = elem.find('./Quiet')
        if quiet is not None and quiet.text.lower() == 'true':
            self.quiet = True
        else:
            self.quiet = False
        delete_list = list(object_key_iter(elem))
        if len(delete_list) > self.conf.max_multi_delete_objects:
            raise MalformedXML()
    except (XMLSyntaxError, DocumentInvalid):
        raise MalformedXML()
    except ErrorResponse:
        raise
    except Exception as e:
        self.logger.error(e)
        raise
    elem = Element('DeleteResult')
    # check bucket existence
    try:
        req.get_response(self.app, 'HEAD')
    except AccessDenied as error:
        body = self._gen_error_body(error, elem, delete_list)
        return HTTPOk(body=body)
    if any(version is not None for _key, version in delete_list):
        # Support deleting specific versions of objects
        for key, version in delete_list:
            if version is not None:
                self.logger.info(f'Deleting version {version} of object {key}')
    def do_delete(base_req, key, version):
        req = copy.copy(base_req)
        req.environ = copy.copy(base_req.environ)
        req.object_name = key
        if version is not None:
            req.version_id = version
        try:
            query = req.gen_multipart_manifest_delete_query(self.app)
            resp = req.get_response(self.app, method='DELETE', query=query,
                                    headers={'Accept': 'application/json'})
            if query:
                try:
                    delete_result = json.loads(resp.body)
                    if delete_result['Errors']:
                        msg_parts = [delete_result['Response Status']]
                        msg_parts.extend(
                            '%s: %s' % (obj, status)
                            for obj, status in delete_result['Errors'])
                        return key, {'code': 'SLODeleteError',
                                     'message': '\n'.join(msg_parts)}
                except (ValueError, TypeError, KeyError):
                    self.logger.exception(
                        'Could not parse SLO delete response: %r',
                        resp.body)
                    return key, {'code': 'SLODeleteError',
                                 'message': 'Unexpected swift response'}
        except NoSuchKey:
            pass
        except ErrorResponse as e:
            return key, {'code': e.__class__.__name__, 'message': e._msg}
        return key, None
    with StreamingPile(self.conf.multi_delete_concurrency) as pile:
        for key, err in pile.asyncstarmap(do_delete, (
                (req, key, version) for key, version in delete_list))):
            if err:
                error = SubElement(elem, 'Error')
                SubElement(error, 'Key').text = key
                SubElement(error, 'Code').text = err['code']
                SubElement(error, 'Message').text = err['message']
            elif not self.quiet:
                deleted = SubElement(elem, 'Deleted')
                SubElement(deleted, 'Key').text = key
    body = tostring(elem)
    return HTTPOk(body=body)

def POST(self, req):

    def object_key_iter(elem):
        for obj in elem.iterchildren('Object'):
            key = obj.find('./Key').text
            if not key:
                raise UserKeyMustBeSpecified()
            version = obj.find('./VersionId')
            if version is not None:
                version = version.text
            yield (key, version)
    max_body_size = min(2 * self.conf.max_multi_delete_objects * MAX_OBJECT_NAME_LENGTH, 10 * 1024 * 1024)
    try:
        xml = req.xml(max_body_size)
        if not xml:
            raise MissingRequestBodyError()
        req.check_md5(xml)
        elem = fromstring(xml, 'Delete', self.logger)
        quiet = elem.find('./Quiet')
        if quiet is not None and quiet.text.lower() == 'true':
            self.quiet = True
        else:
            self.quiet = False
        delete_list = list(object_key_iter(elem))
        if len(delete_list) > self.conf.max_multi_delete_objects:
            raise MalformedXML()
    except (XMLSyntaxError, DocumentInvalid):
        raise MalformedXML()
    except ErrorResponse:
        raise
    except Exception as e:
        self.logger.error(e)
        raise
    elem = Element('DeleteResult')
    try:
        req.get_response(self.app, 'HEAD')
    except AccessDenied as error:
        body = self._gen_error_body(error, elem, delete_list)
        return HTTPOk(body=body)
    if any((version is not None for (_key, version) in delete_list)):
        for (key, version) in delete_list:
            if version is not None:
                self._delete_version(req, key, version, elem)
            else:
                self._delete_object(req, key, elem)
    else:
        for (key, _) in delete_list:
            self._delete_object(req, key, elem)
    body = tostring(elem)
    return HTTPOk(body=body)

def _delete_version(self, req, key, version, elem):
    req.object_name = key
    req.version_id = version

def _delete_object(self, req, key, elem):
    req.object_name = key

def run_cmd(self, command_list, allow_fail=False, error_msg=None, cwd=None):
    if isinstance(command_list, str):
        command_list = shlex.split(command_list)
    elif not isinstance(command_list, list):
        raise LAVABug('commands to run_cmd need to be a list or a string')
    command_list = ['nice'] + [str(s) for s in command_list]
    self.logger.debug("Calling: '%s'", "' ".join(command_list))
    start = time.time()
    proc = subprocess.Popen(command_list, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=1, universal_newlines=True, encoding='utf-8', errors='replace')
    poller = select.epoll()
    poller.register(proc.stdout, select.EPOLLIN)
    poller.register(proc.stderr, select.EPOLLIN)
    while proc.poll() is None:
        for (fd, event) in poller.poll():
            if event is not select.EPOLLIN:
                continue
            if fd == proc.stdout.fileno():
                line = proc.stdout.readline()
                self.logger.debug('>> %s', line)
            elif fd == proc.stderr.fileno():
                line = proc.stderr.readline()
                self.logger.error('>> %s', line)
    for line in proc.stdout.readlines():
        self.logger.debug('>> %s', line)
    for line in proc.stderr.readlines():
        self.logger.error('>> %s', line)
    ret = proc.wait()
    self.logger.debug('Returned %d in %s seconds', ret, int(time.time() - start))
    if ret and (not allow_fail):
        self.logger.error("Unable to run '%s'", command_list)
        raise self.command_exception(error_msg)

def solve_output(self, **input_types):
    solved_outputs = self.outputs
    for (output_name, spec) in solved_outputs.items():
        if not spec.qiime_type.is_concrete():
            raise TypeError('Solved output %r must be a concrete type, not %r' % (output_name, spec.qiime_type))
    return solved_outputs

