from xml.sax.saxutils import escape

def setAuthors(template, authors):
    text = ''
    for (name, href) in authors:
        escaped_name = escape(name)
        escaped_href = escape(href)
        anchor = f'<a href="{escaped_href}">{escaped_name}</a>'
        if (name, href) == authors[-1]:
            if len(authors) == 1:
                text = anchor
            else:
                text += 'and ' + anchor
        else:
            text += anchor + ','
    childNodes = microdom.parseString('<span>' + text + '</span>').childNodes
    for node in domhelpers.findElementsWithAttribute(template, 'class', 'authors'):
        node.childNodes.extend(childNodes)
    head = domhelpers.findNodesNamed(template, 'head')[0]
    authors = [microdom.parseString('<link rel="author" href="%s" title="%s"/>' % (escaped_href, escaped_name)).childNodes[0] for (name, href) in authors]
    head.childNodes.extend(authors)

def dotedges(expr, atom=lambda x: not isinstance(x, Basic), pos=(), repeat=True):
    if atom(expr):
        return []
    else:
        expr_str = purestr(expr)
        arg_strs = [purestr(arg) for arg in expr.args]
        if repeat:
            expr_str += '_%s' % str(pos)
            arg_strs = [arg_str + '_%s' % str(pos + (i,)) for (i, arg_str) in enumerate(arg_strs)]
        return ['"%s" -> "%s";' % (expr_str, arg_str) for arg_str in arg_strs]

