def unregisterConsumer(self, consumerId: str) -> bool:
    method = '/consumers/%s' % self.sanitize(consumerId)
    try:
        response = self.conn.request_delete(method, description=_('Unregistering system'))
        if response.status_code == 204:
            return True
        else:
            return False
    except Exception as e:
        return False

def unregisterConsumer(self, consumerId: str) -> bool:
    method = '/consumers/%s' % self.sanitize(consumerId)
    try:
        result = self.conn.request_delete(method, description=_('Unregistering system'))
        return result.status == 204
    except Exception as e:
        return False

def rd(self, signal):
    name = self.top_level.top_name + '.' + self.top_level.dut_name + '.' + self.namespace.get_name(signal)
    self.ipc.send(MessageRead(name))
    reply = self.ipc.recv()
    assert isinstance(reply, MessageReadReply)
    if reply.value < 0:
        reply.value = self.handle_negative(reply.value)
    reply.value = self.cleanup_lsb(reply.value)
    return reply.value

    def handle_negative(self, value):
        return abs(value)

    def cleanup_lsb(self, value):
        return value & 255

import logging
logging.basicConfig(level=logging.INFO)
eval_logger = logging.getLogger(__name__)

def get_metric(name):
    try:
        return METRIC_REGISTRY[name]
    except KeyError:
        eval_logger.warning(f"Could not find registered metric '{name}' in lm-eval, searching in HF Evaluate library...")
        try:
            metric_object = evaluate.load(name)
            return metric_object.compute
        except Exception:
            eval_logger.error('{} not found in the evaluate library!'.format(name), 'Please check https://huggingface.co/evaluate-metric')

def add_image(self, can_remove=True):

    class ImageSettings(object):

        def __init__(self, images):
            self.key = uuid.uuid4()
            self.image_name = cps.ImageNameSubscriber('Select the input image', 'None')
            self.setting_group = cps.SettingGroup('Image Settings', [self.image_name])
            if can_remove:

                def remove(images=images, key=self.key):
                    index = [x.key for x in images].index(key)
                    del images[index]
                self.remove_button = cps.DoSomething('Remove above image', 'Remove', remove)
                self.setting_group.add(self.remove_button)

        def settings(self):
            return self.setting_group.settings()

        def visible_settings(self):
            return self.setting_group.visible_settings()
    self.images.append(ImageSettings(self.images))

def add_image(self, can_remove=True):
    image_settings = cps.SettingGroup()
    image_settings.key = uuid.uuid4()
    image_settings.image_name = cps.ImageNameSubscriber('Select the input image', 'None')
    if can_remove:

        def remove(images=self.images, key=image_settings.key):
            index = [x.key for x in images].index(key)
            del images[index]
        image_settings.remove_button = cps.DoSomething('Remove above image', 'Remove', remove)
    self.images.append(image_settings)

