def visit_ConstantNode(self, node):
    escaped_value = self.escape_value(node.value)
    self.write("'" + escaped_value + "'")
    def escape_value(self, value):
        return str(value).replace("'", "\'").replace("\", "\\")

def visit_ConstantNode(self, node):
    escaped_value = str(node.value).replace("'", "\\'").replace('"', '\\"')
    self.write("'" + escaped_value + "'")

def on_task_metainfo(self, task, config):
    for entry in task.entries:
        if not entry.has_lazy_data():
            entry.take_snapshot('after_input')
        else:
            log.warning('Entry %s has lazy data, skipping snapshot.' % entry['title'])

def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        saved_value = self._saved
        self._saved = None
        return saved_value
    else:
        return self._generator.next()

def _reset(self):
    self.agentPos = self.startPos
    self.agentDir = 0
    self.stepCount = 0
    self._render()
    return np.array([])

def find_target_size(model_name):
    target_sizes = {'VGG-Face': (224, 224), 'Facenet': (160, 160), 'Facenet512': (160, 160), 'OpenFace': (96, 96), 'DeepFace': (152, 152), 'DeepID': (47, 55), 'Dlib': (150, 150), 'ArcFace': (112, 112), 'SFace': (112, 112)}
    if model_name not in target_sizes.keys():
        raise ValueError(f'unimplemented model name - {model_name}')
    return target_sizes[model_name]

def copy(self):
    self.temp_dir = tempfile.mkdtemp(suffix='', prefix='barman-')
    try:
        self._progress_init()
        _logger.info('Copy started (safe before %r)', self.safe_horizon)
        for item in self.item_list:
            if not item.is_directory:
                continue
            _logger.info(self._progress_message('analyze %s' % item))
            self._analyze_directory(item)
            _logger.info(self._progress_message('create destination directories and delete unknown files for %s' % item))
            self._create_dir_and_purge(item)
        pool = Pool(processes=self.workers, initializer=_init_worker, initargs=(self._execute_job,))
        for _ in pool.imap_unordered(_run_worker, self._job_generator()):
            pass
        for item in self.item_list:
            if isinstance(item, PGCONTROL_CLASS):
                _logger.info(self._progress_message('Executing final step for %s' % item))
                self._execute_pgcontrol(item)
    except:
        _logger.info('Copy failed (safe before %s)', self.safe_horizon)
        raise
    else:
        _logger.info('Copy finished (safe before %s)', self.safe_horizon)
    finally:
        shutil.rmtree(self.temp_dir)
        self.temp_dir = None

def subset_for(self, selected_asset_keys: AbstractSet[AssetKey]) -> 'AssetsDefinition':
    check.invariant(self.can_subset, f'Attempted to subset AssetsDefinition for {self.node_def.name}, but can_subset=False.')
    filtered_asset_deps = {key: value for (key, value) in self._asset_deps.items() if key in selected_asset_keys}
    for key in list(filtered_asset_deps.keys()):
        filtered_asset_deps[key] = {dep for dep in filtered_asset_deps[key] if dep in selected_asset_keys}
    return AssetsDefinition(asset_keys_by_input_name=self._asset_keys_by_input_name, asset_keys_by_output_name=self._asset_keys_by_output_name, node_def=self.node_def, partitions_def=self.partitions_def, partition_mappings=self._partition_mappings, asset_deps=filtered_asset_deps, can_subset=self.can_subset, selected_asset_keys=selected_asset_keys & self.asset_keys)

