def _generateColumnHeader(self, obj, **args):
    result = []
    try:
        role = args.get('role', obj.getRole())
    except:
        role = None
    if role in [pyatspi.ROLE_COLUMN_HEADER, pyatspi.ROLE_TABLE_COLUMN_HEADER]:
        return result
    try:
        table = obj.parent.queryTable()
    except:
        pass
    else:
        index = self._script.utilities.cellIndex(obj)
        columnIndex = table.getColumnAtIndex(index)
        if columnIndex >= 0:
            header = table.getColumnHeader(columnIndex)
            if header:
                desc = self._script.utilities.displayedText(header)
            else:
                desc = table.getColumnDescription(columnIndex)
            if desc and len(desc):
                text = desc
                if args['mode'] == 'speech':
                    if settings.speechVerbosityLevel == settings.VERBOSITY_LEVEL_VERBOSE and (not args.get('formatType', None) in ['basicWhereAmI', 'detailedWhereAmI']):
                        text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                elif args['mode'] == 'braille':
                    text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                result.append(text)
    return result

def get_sequence(self, name):
    if name in self.saved_sequences:
        with open(self.sequence_dir + name + '.seq', 'rb') as infile:
            sequence = pickle.load(infile)
    else:
        raise FileNotFoundError(f'Error: No sequence with name "{name}" in saved sequences.')
    return sequence

def _check_chunk_length(self, cursor, value):
    if self.cluster.version() >= '3.0':
        table_metadata = cursor.get_metadata().keyspaces['ks'].tables['test_table']
    else:
        raise NotImplementedError('Metadata API for versions below 3.0 is not supported.')
    params = table_metadata.options
    assert 'sstable_compression' in params, "Looking for 'sstable_compression', but could not find it."
    chunk_length = int(params['chunk_length_kb'])
    assert chunk_length == value, 'Expected chunk_length: %s.  We got: %s' % (value, chunk_length)

def _check_chunk_length(self, cursor, value):
    if self.cluster.version() >= '3.0':
        table_metadata = self.cluster.metadata.keyspaces['ks'].tables['test_table']
    else:
        describe_table_query = "SELECT * FROM system_schema.tables WHERE keyspace_name='ks' AND table_name='test_table';"
        rows = cursor.execute(describe_table_query)
        results = rows[0]
        table_metadata = results
    chunk_length = table_metadata.sstable_compression['chunk_length_kb']
    assert chunk_length == value, 'Expected chunk_length: %s.  We got: %s' % (value, chunk_length)

def __str__(self):
    modifiers = ' '.join(self.type_modifiers)
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    templated_types = '<%s>' % ', '.join(self.templated_types) if self.templated_types else ''
    suffix = '%s %s%s %s %s' % (modifiers, self.type_name, syntax, templated_types, self.name)
    if self.default:
        suffix += ' = ' + self.default
    return self._StringHelper(self.__class__.__name__, suffix)

def __str__(self):
    modifiers = ' '.join(self.type_modifiers)
    templated_types = ''
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    suffix = '%s %s%s %s' % (modifiers, self.type_name, syntax, self.name)
    if self.default:
        suffix += ' = ' + self.default
    return self._StringHelper(self.__class__.__name__, suffix)

def SBROM_KeyDerivation(self, aeskeytype, key, salt, requestedlen, destaddr):
    result = bytearray()
    buffer = bytearray(b'\x00' * 67)
    if aeskeytype - 1 > 4 or 1 << aeskeytype - 1 & 23 == 0:
        return 4060086274
    if requestedlen > 255 or requestedlen << 28 & 4294967295:
        return 4060086275
    if 0 >= len(key) > 32:
        return 4060086275
    bufferlen = len(salt) + 3 + len(key)
    iterlength = requestedlen + 15 >> 4
    if len(key) == 0:
        keyend = 1
    else:
        buffer[1:1 + len(key)] = key
        keyend = len(key) + 1
    saltstart = keyend + 1
    if len(salt) > 0:
        buffer[saltstart:saltstart + len(salt)] = salt
    buffer[saltstart + len(salt):saltstart + len(salt) + 4] = pack('<I', 8 * requestedlen)
    for i in range(0, iterlength):
        buffer[0] = i + 1
        dstaddr = self.SBROM_AesCmac(aeskeytype, 0, buffer, 0, bufferlen, destaddr)
        if dstaddr != 0:
            for field in self.read32(dstaddr + 264, 4):
                result.extend(pack('<I', field))
    return result

def SBROM_KeyDerivation(self, aeskeytype, key, salt, requestedlen, destaddr):
    result = bytearray()
    buffer = bytearray(b'\x00' * 67)
    if aeskeytype - 1 > 4 or 1 << aeskeytype - 1 & 23 == 0:
        return 4060086274
    if requestedlen > 255 or requestedlen << 28 & 4294967295:
        return 4060086275
    if 0 >= len(key) > 32:
        return 4060086275
    bufferlen = len(salt) + 3 + len(key)
    iterlength = requestedlen + 15 >> 4
    if len(key) == 0:
        keyend = 1
    else:
        buffer[1:1 + len(key)] = key
        keyend = len(key) + 1
    saltstart = keyend + 1
    if len(salt) > 0:
        buffer[saltstart:saltstart + len(salt)] = salt
    if len(buffer) < bufferlen:
        return 4060086276
    buffer[saltstart + len(salt):saltstart + len(salt) + 4] = pack('<I', 8 * requestedlen)
    for i in range(0, iterlength):
        buffer[0] = i + 1
        dstaddr = self.SBROM_AesCmac(aeskeytype, 0, buffer, 0, bufferlen, destaddr)
        if dstaddr != 0:
            for field in self.read32(dstaddr + 264, 4):
                result.extend(pack('<I', field))
    return result

def decrypt(self):
    encryption_context = self.parameters.get('EncryptionContext')
    if encryption_context != self.kms_backend.get_encryption_context(self.parameters.get('KeyId')):
        raise ValueError('EncryptionContext does not match. Decryption refused.')
    value = self.parameters.get('CiphertextBlob')
    try:
        return json.dumps({'Plaintext': base64.b64decode(value).decode('utf-8'), 'KeyId': 'key_id'})
    except UnicodeDecodeError:
        return json.dumps({'Plaintext': value})

