def genome_map(_input, max_wraps=0):
    from utilities.helper_methods import python_filter
    (used_input, current_depth, current_max_depth, nodes) = (0, 0, 0, 1)
    (wraps, output, production_choices) = (-1, [], [])
    unexpanded_symbols = [(params['BNF_GRAMMAR'].start_rule, 0)]
    while wraps < max_wraps and len(unexpanded_symbols) > 0 and (current_max_depth <= params['MAX_TREE_DEPTH']):
        if used_input % len(_input) == 0 and used_input > 0 and any([i[0][1] == 'NT' for i in unexpanded_symbols]):
            wraps += 1
        current_item = unexpanded_symbols.pop(0)
        (current_symbol, current_depth) = (current_item[0], current_item[1])
        if current_max_depth < current_depth:
            current_max_depth = current_depth
        if current_symbol[1] != params['BNF_GRAMMAR'].NT:
            output.append(current_symbol[0])
        else:
            production_choices = params['BNF_GRAMMAR'].rules[current_symbol[0]]
            current_production = _input[used_input % len(_input)] % len(production_choices)
            used_input += 1
            children = []
            for prod in production_choices[current_production]:
                children.append([prod, current_depth + 1])
            NT_kids = [child for child in children if child[0][1] == 'NT']
            if any(NT_kids):
                nodes += len(NT_kids)
            else:
                nodes += 1
            unexpanded_symbols = children + unexpanded_symbols
    if len(unexpanded_symbols) > 0:
        return (output, _input, None, nodes, True, current_max_depth + 1, used_input)
    output = ''.join(output)
    if params['BNF_GRAMMAR'].python_mode:
        output = python_filter(output)
    return (output, _input, None, nodes, False, current_max_depth + 1, used_input)
    if current_max_depth > params['MAX_TREE_DEPTH']:
        return (output, _input, None, nodes, True, current_max_depth, used_input)

def _decode_to(cls: Type[T], raw_rlp: RLP) -> T:
    if isinstance(cls, type(Tuple[Uint, ...])) and cls._name == 'Tuple':
        ensure(type(raw_rlp) == list, RLPDecodingError)
        if cls.__args__[1] == ...:
            args = []
            for raw_item in raw_rlp:
                args.append(_decode_to(cls.__args__[0], raw_item))
            return tuple(args)
        else:
            args = []
            for (t, raw_item) in zip(cls.__args__, raw_rlp):
                args.append(_decode_to(t, raw_item))
            return tuple(args)
    elif cls == Union[Bytes0, Bytes20]:
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        if len(raw_rlp) == 0:
            return Bytes0()
        elif len(raw_rlp) == 20:
            return Bytes20(raw_rlp)
        else:
            raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))
    elif isinstance(cls, type(List[Bytes])) and cls._name == 'List':
        ensure(type(raw_rlp) == list, RLPDecodingError)
        items = []
        for raw_item in raw_rlp:
            items.append(_decode_to(cls.__args__[0], raw_item))
        return items
    elif isinstance(cls, type(Union[Bytes, List[Bytes]])) and cls.__origin__ == Union:
        if len(cls.__args__) != 2 or Bytes not in cls.__args__:
            raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))
        if isinstance(raw_rlp, Bytes):
            return raw_rlp
        elif cls.__args__[0] == Bytes:
            return _decode_to(cls.__args__[1], raw_rlp)
        else:
            return _decode_to(cls.__args__[0], raw_rlp)
    elif issubclass(cls, bool):
        if raw_rlp == b'\x01':
            return cls(True)
        elif raw_rlp == b'':
            return cls(False)
        else:
            raise TypeError('Cannot decode {} as {}'.format(raw_rlp, cls))
    elif issubclass(cls, Bytes):
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        return raw_rlp
    elif issubclass(cls, (Uint, U256, Uint64)):
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        return cls.from_be_bytes(raw_rlp)
    elif is_dataclass(cls):
        ensure(type(raw_rlp) == list, RLPDecodingError)
        assert isinstance(raw_rlp, list)
        if len(raw_rlp) != len(fields(cls)):
            raise RLPDecodingError('Expected {} items, got {}'.format(len(fields(cls)), len(raw_rlp)))
        args = []
        for (field, rlp_item) in zip(fields(cls), raw_rlp):
            args.append(_decode_to(field.type, rlp_item))
        return cls(*args)
    else:
        raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))

import ast

def exports(self):
    from pyflyby._importclns import ImportStatement, ImportSet
    module = self.module
    try:
        members = module.__all__
    except AttributeError:
        members = dir(module)
        members = [n for n in members if not n.startswith('_')]

        def from_this_module(name):
            source = ast.parse(inspect.getsource(module))
            for node in ast.walk(source):
                if isinstance(node, ast.FunctionDef) or isinstance(node, ast.Assign):
                    if name in [n.id for n in node.targets] or name == node.name:
                        return True
            return False
        members = [n for n in members if from_this_module(n)]
    else:
        if not all((type(s) == str for s in members)):
            raise Exception('Module %r contains non-string entries in __all__' % (str(self.name),))
    members = [(n, None) for n in members if '.' not in n]
    if not members:
        return None
    return ImportSet([ImportStatement.from_parts(str(self.name), members)])

def exports(self):
    from pyflyby._importclns import ImportStatement, ImportSet
    module = self.module
    try:
        members = module.__all__
    except AttributeError:
        members = dir(module)
        members = [n for n in members if not n.startswith('_')]
        members = [n for n in members if n in module.__dict__]
    else:
        if not all((type(s) == str for s in members)):
            raise Exception('Module %r contains non-string entries in __all__' % (str(self.name),))
    members = [(n, None) for n in members if '.' not in n]
    if not members:
        return None
    return ImportSet([ImportStatement.from_parts(str(self.name), members)])

def visit_Ac_Implied_Do(self, o, **kwargs):
    result = []
    for item in o.items:
        processed_item = self.visit(item, **kwargs)
        result.append(processed_item)
    return result if result else None

def visit_Ac_Implied_Do(self, o, **kwargs):
    results = []
    for item in o:
        result = self.visit(item, **kwargs)
        results.append(result)
    return results if results else None

def primary_key(self):
    from kart.working_copy import db_adapter
    with self.engine.connect() as conn:
        if self.db_type == 'GPKG':
            return db_adapter.pk(conn, self.table)
        else:
            raise NotImplementedError('Primary key retrieval is not implemented for this database type.')

def test_run_qobj(self):
    try:
        simulator = qiskitsimulator.QISKitCppSimulator()
    except FileNotFoundError as fnferr:
        raise unittest.SkipTest('cannot find {} in path'.format(fnferr))
    result = simulator.run(self.q_job)
    expected2 = {'000 000': 18, '001 001': 15, '010 010': 13, '011 011': 11, '100 100': 10, '101 101': 10, '110 110': 12, '111 111': 11}
    self.assertEqual(result.get_counts('test_circuit2'), expected2)

def process_dependencies(self, task, deplist, uowcommit, delete=False):
    if delete:
        if not self.cascade.delete_orphan or self.post_update:
            for obj in deplist:
                childlist = self.get_object_dependencies(obj, uowcommit, passive=self.passive_deletes)
                if childlist is not None:
                    for child in childlist.deleted_items():
                        if child is not None and (not childlist.hasparent(child)):
                            uowcommit.register_object(child, isdelete=True)
                            for c in self.mapper.cascade_iterator('delete', child):
                                uowcommit.register_object(c, isdelete=True)
                    for child in childlist.unchanged_items():
                        if child is not None:
                            uowcommit.register_object(child, isdelete=True)
                            for c in self.mapper.cascade_iterator('delete', child):
                                uowcommit.register_object(c, isdelete=True)
    else:
        for obj in deplist:
            childlist = self.get_object_dependencies(obj, uowcommit, passive=True)
            if childlist is not None:
                for child in childlist.added_items():
                    self._synchronize(obj, child, None, False, uowcommit)
                    self._conditional_post_update(child, uowcommit, [obj])
                for child in childlist.deleted_items():
                    if not self.cascade.delete_orphan and (not self._get_instrumented_attribute().hasparent(child)):
                        self._synchronize(obj, child, None, True, uowcommit)

