def dict_for_mongo(_dict):
    for (key, value) in _dict.items():
        if _is_invalid_for_mongo(key):
            del _dict[key]
            key = _encode_for_mongo(key)
        if isinstance(value, list):
            _dict[key] = [dict_for_mongo(obj) if isinstance(obj, dict) else obj for obj in value]
        elif isinstance(value, dict):
            _dict[key] = dict_for_mongo(value)
        else:
            _dict[key] = str(value)
    return _dict

def append_changelog_changes_collections(builder: RstBuilder, changelog_entry: ChangelogEntry, is_last: bool) -> PluginDataT:
    result: PluginDataT = []
    if changelog_entry.changed_collections:
        if is_last:
            builder.add_section('Included Collections', 1)
        else:
            builder.add_section('Changed Collections', 1)
        for (collector, collection_version, prev_collection_version) in changelog_entry.changed_collections:
            if is_last:
                msg = f'{collector.collection} with version {collection_version}.'
                if prev_collection_version is not None:
                    msg += f' This was upgraded from version {prev_collection_version}.'
            elif prev_collection_version is None:
                msg = f'{collector.collection} was upgraded to version {collection_version}.'
            else:
                msg = f'{collector.collection} was upgraded from'
                msg += f' version {prev_collection_version} to version {collection_version}.'
            msg += '\n'
            changelog = collector.changelog
            if changelog:
                release_entries = changelog.generator.collect(squash=True, after_version=prev_collection_version, until_version=collection_version)
                if not release_entries:
                    msg += 'The collection did not have a changelog in this version.'
                elif release_entries[0].empty:
                    msg += 'There are no changes recorded in the changelog.'
                else:
                    result.append((collector.collection, f'{collector.collection}.', changelog.generator, release_entries[0]))
                    msg += 'The changes are reported in the combined changelog below.'
            else:
                msg += 'Unfortunately, this collection does not provide changelog data in a format '
                msg += 'that can be processed by the changelog generator.'
                msg += f' Please check the changelog here: {collector.changelog_url}'
            builder.add_list_item(msg)
        builder.add_raw_rst('')
    return result

def from_dist(cls, dist, dependency_links, find_tags=False):
    location = os.path.normcase(os.path.abspath(dist.location))
    comments = []
    from pip.vcs import vcs, get_src_requirement
    if vcs.get_backend_name(location):
        editable = True
        try:
            req = get_src_requirement(dist, location, find_tags)
        except InstallationError as exc:
            logger.warn('Error when trying to get requirement for VCS system %s, falling back to uneditable format' % exc)
            req = None
        if req is None:
            logger.warn('Could not determine repository location of %s' % location)
            comments.append('## !! Could not determine repository location')
            req = dist.as_requirement()
            editable = False
    else:
        editable = False
        req = dist.as_requirement()
        specs = req.specs
        assert len(specs) == 1 and specs[0][0] == '=='
        version = specs[0][1]
        ver_match = cls._rev_re.search(version)
        date_match = cls._date_re.search(version)
        if ver_match or date_match:
            svn_backend = vcs.get_backend('svn')
            if svn_backend:
                svn_location = svn_backend().get_location(dist, dependency_links)
            if not svn_location:
                logger.warn('Warning: cannot find svn location for %s' % req)
                comments.append('## ERROR: could not find svn URL in dependency_links for this package. Please check the provided links.')
                raise ValueError('SVN location not found for package: %s' % req)
            else:
                comments.append('# Installing as editable to satisfy requirement %s:' % req)
                if ver_match:
                    rev = ver_match.group(1)
                else:
                    rev = '{%s}' % date_match.group(1)
                editable = True
                req = '%s@%s#egg=%s' % (svn_location, rev, cls.egg_name(dist))
    return cls(dist.project_name, req, editable, comments)

