def parse_attr(self, attr):

    def tilde_unescape(string):

        def repl(m):
            if m.group(1) == '1':
                return '/'
            elif m.group(1) == 'a':
                return ','
            elif m.group(1) == 'b':
                return '@'
        s1 = self.tildeEscape_re.sub(repl, string)
        return re.sub('~0', '~', s1)
    attrs = attr.split('/')
    processed_attrs = []
    for a in attrs:
        if a.startswith('@key'):
            processed_attrs.append('key_value')
        else:
            processed_attrs.append(tilde_unescape(a))
    return processed_attrs

def compile(self, lang):
    dest = self.translated_base_path(lang)
    if not self.is_translation_available(lang) and (not self.config['SHOW_UNTRANSLATED_POSTS']):
        return
    LocaleBorg().set_locale(lang)
    self.compile_html(self.translated_source_path(lang), dest, self.is_two_file, self, lang)
    Post.write_depfile(dest, self._depfile[dest], post=self, lang=lang)
    signal('compiled').send({'source': self.translated_source_path(lang), 'dest': dest, 'post': self, 'lang': lang})
    if self.publish_later:
        LOGGER.notice('{0} is scheduled to be published in the future ({1})'.format(self.source_path, self.date))

def get(self, name: str) -> Compute:
    (response, rest_obj) = self._operation.get(self._operation_scope.resource_group_name, self._workspace_name, name, cls=get_http_response_and_deserialized_from_pipeline_response)
    response_json = json.loads(response.internal_response.text)
    xds_error_code = 'XDSRestartRequired'
    warnings = response_json['properties'].get('warnings', [])
    xds_warning = next((warning for warning in warnings if warning['code'] == xds_error_code), None)
    if xds_warning:
        logging.critical(xds_warning['message'])
    return Compute._from_rest_object(rest_obj)

