def evaluate(self, eval_points):
    eval_points = numpy.asarray(eval_points)
    if numpy.any(numpy.isnan(eval_points)):
        raise ValueError('The list of points where the function is evaluated can not contain nan values.')
    basis_values = self._compute_matrix(eval_points)
    derivative_values = self._compute_derivative_matrix(eval_points)
    return numpy.vstack((basis_values, derivative_values))

