def test_decimal_builtins_2(self):
    d = ibis.literal('5.245')
    dc = d.cast('decimal(12,5)')
    cases = [(dc % 5, Decimal('0.245')), (dc.fillna(0), Decimal('5.245')), (dc.exp(), 189.6158), (dc.log(), 1.65728), (dc.log2(), 2.39094), (dc.log10(), 0.71975), (dc.sqrt(), 2.29019), (dc.zeroifnull(), Decimal(5.245)), (-dc, Decimal('-5.245'))]
    for (expr, expected) in cases:
        result = self.con.execute(expr)

        def approx_equal(a, b, eps=0.0001):
            assert abs(a - b) < eps
        approx_equal(result, expected)

import logging

class YourClass:

    def decompile(self, data, ttFont):
        (format, n, stringOffset) = struct.unpack('>HHH', data[:6])
        expectedStringOffset = 6 + n * nameRecordSize
        if stringOffset != expectedStringOffset:
            self.warn("'name' table stringOffset incorrect. Expected: %s; Actual: %s", expectedStringOffset, stringOffset)
        stringData = data[stringOffset:]
        data = data[6:]
        self.names = []
        for i in range(n):
            if len(data) < 12:
                break
            (name, data) = sstruct.unpack2(nameRecordFormat, data, NameRecord())
            name.string = stringData[name.offset:name.offset + name.length]
            assert len(name.string) == name.length
            del name.offset, name.length
            self.names.append(name)

    def warn(self, message, *args):
        logging.warning(message % args)

