def visit_Module(self, node) -> str:
    docstring = getattr(node, 'docstring_comment', None)
    buf = [self.comment(docstring.value)] if docstring is not None else []
    filename = getattr(node, '__file__', None)
    if filename is not None:
        self._module = Path(filename).stem
    self.reset_state()
    body_dict: Dict[ast.AST, str] = OrderedDict()
    for b in node.body:
        if not isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    for b in node.body:
        if isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    buf += [body_dict[b] for b in node.body]
    return '\n'.join(buf)

def reset_state(self):
    self._imported_names = {}
    self._usings.clear()

class P11CryptoPluginException(Exception):
    message = u._('General exception')

class P11CryptoPluginKeyException(P11CryptoPluginException):
    message = u._('Key related exception')

class P11CryptoPluginSessionException(P11CryptoPluginException):
    message = u._('Session related exception')

class P11CryptoPluginOperationException(P11CryptoPluginException):
    message = u._('Operation related exception')

def _check_error(self, value):
    if value != CKR_OK:
        if value in [CKR_KEY_HANDLE_INVALID, CKR_KEY_SIZE_RANGE]:
            raise P11CryptoPluginKeyException(u._('HSM returned response code: {hex_value} {code}'.format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????'))))
        elif value in [CKR_SESSION_CLOSED, CKR_SESSION_HANDLE_INVALID]:
            raise P11CryptoPluginSessionException(u._('HSM returned response code: {hex_value} {code}'.format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????'))))
        elif value in [CKR_FUNCTION_FAILED, CKR_OPERATION_NOT_INITIALIZED]:
            raise P11CryptoPluginOperationException(u._('HSM returned response code: {hex_value} {code}'.format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????'))))
        else:
            raise P11CryptoPluginException(u._('HSM returned response code: {hex_value} {code}'.format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????'))))

def _check_error(self, value):
    if value != CKR_OK:
        if value in (CKR_PIN_INCORRECT, CKR_PIN_INVALID):
            raise P11CryptoPluginException(u._('Authentication error: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))
        elif value in (CKR_SESSION_CLOSED, CKR_SESSION_HANDLE_INVALID):
            raise P11CryptoPluginException(u._('Session error: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))
        else:
            raise P11CryptoPluginException(u._('HSM returned response code: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))

def setitem_from_path(self, path, value, trans=None):
    (path, item) = (path[:-1], path[-1])
    struct = self.struct
    for p in range(len(path)):
        part = path[p]
        if part.startswith('['):
            struct = struct[eval(part[1:-1])]
        else:
            struct = struct[part]
        if struct is None:
            return
    if isinstance(struct, HandleClass):
        struct = self.handle_join(struct)
    if isinstance(struct, (list, tuple)):
        pos = int(item)
        if pos < len(struct):
            struct[int(item)] = value
    elif isinstance(struct, dict):
        if item in struct.keys():
            struct[item] = value
    elif hasattr(struct, item):
        setattr(struct, item, value)
    else:
        return
    self.update_db(trans)

def run_job(job_id):
    job = fetch('Job', id=job_id)
    if job.status == 'Running':
        return {'error': 'Job is already running.'}
    targets = job.compute_targets()
    if hasattr(job, 'has_targets'):
        if job.has_targets and (not targets):
            return {'error': 'Set devices or pools as targets first.'}
        if not job.has_targets and targets:
            return {'error': 'This service should not have targets configured.'}
    response = make_rest_api_request(job_id)
    if response.get('error'):
        return response
    return job.serialized

