async def encrypt(self, room_id: RoomID, event_type: EventType, content: Union[Serializable, JSON]) -> Tuple[EventType, EncryptedMegolmEventContent]:
    lock = asyncio.Lock()
    try:
        encrypted = await self.crypto.encrypt_megolm_event(room_id, event_type, content)
    except EncryptionError:
        self.log.debug('Got EncryptionError, sharing group session and trying again')
        async with lock:
            if not self.crypto.is_sharing_group_session(room_id):
                users = UserProfile.all_in_room(room_id, self._id_prefix, self._id_suffix, self.bot_mxid)
                await self.crypto.share_group_session(room_id, [profile.user_id for profile in users])
            else:
                await self.crypto.wait_group_session(room_id)
        encrypted = await self.crypto.encrypt_megolm_event(room_id, event_type, content)
    return (EventType.ROOM_ENCRYPTED, encrypted)

async def encrypt(self, room_id: RoomID, event_type: EventType, content: Union[Serializable, JSON]) -> Tuple[EventType, EncryptedMegolmEventContent]:
    try:
        encrypted = await self.crypto.encrypt_megolm_event(room_id, event_type, content)
    except EncryptionError:
        self.log.debug('Got EncryptionError, sharing group session and trying again')
        if not self.crypto.is_sharing_group_session(room_id):
            users = UserProfile.all_in_room(room_id, self._id_prefix, self._id_suffix, self.bot_mxid)
            await self.crypto.share_group_session(room_id, [profile.user_id for profile in users])
        else:
            await self.crypto.wait_group_session(room_id)
        encrypted = await self.crypto.encrypt_megolm_event(room_id, event_type, content)
    return (EventType.ROOM_ENCRYPTED, encrypted)

import os
import requests
import concurrent.futures

def download(self, globus=True, verbose=False, **kwargs):
    path = os.path.join(self.config.local_cache_dir, self.mdf['source_id'])
    if os.path.isdir(path):
        if self.dataset.splits:
            missing_files = []
            for split in self.dataset.splits:
                if split.path[0] == '/':
                    split.path = split.path[1:]
                if not os.path.isfile(os.path.join(path, split.path)):
                    missing_files.append(split.path)
            if len(missing_files) > 0:
                logger.info(f'Dataset will be redownloaded, following files are missing: {missing_files}')
            else:
                return self
        elif len(os.listdir(path)) >= 1:
            return self
        else:
            logger.info('Dataset will be redownloaded, expected file is missing')
    res = self.forge_client.search(f"mdf.source_id:{self.mdf['source_id']}", advanced=True)
    if globus:
        self.forge_client.globus_download(res, dest=self.config.local_cache_dir, dest_ep=self.config.destination_endpoint, interval=kwargs.get('interval', 20), download_datasets=True)
    else:
        https_config = {'source_ep_id': '82f1b5c6-6e9b-11e5-ba47-22000b92c6ec', 'base_url': 'https://data.materialsdatafacility.org', 'folder_to_crawl': f"/foundry/{self.mdf['source_id']}/", 'source_id': self.mdf['source_id']}
        task_list = list(recursive_ls(self.transfer_client, https_config['source_ep_id'], https_config['folder_to_crawl']))
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = {executor.submit(download_file, task, https_config): task for task in task_list}
            for future in concurrent.futures.as_completed(futures):
                try:
                    future.result()
                except Exception as e:
                    logger.error(f'Error downloading file: {e}')
    if os.path.isdir(path):
        if self.dataset.splits:
            missing_files = []
            for split in self.dataset.splits:
                if split.path[0] == '/':
                    split.path = split.path[1:]
                if not os.path.isfile(os.path.join(path, split.path)):
                    missing_files.append(split.path)
            if len(missing_files) > 0:
                raise FileNotFoundError(f'Downloaded directory does not contain the following files: {missing_files}')
        elif len(os.listdir(path)) < 1:
            raise FileNotFoundError('Downloaded directory does not contain the expected file')
    else:
        raise NotADirectoryError('Unable to create directory to download data')
    return self

