def test_infrastructure_hosts_crud(appliance, setup_provider):
    host = setup_provider.hosts.all()[0]
    new_custom_id = f'Edit host data. {fauxfactory.gen_alphanumeric()}'
    with update(host, from_details=False):
        host.custom_ident = new_custom_id
    assert navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier') == new_custom_id
    new_custom_id = f'Edit host data. {fauxfactory.gen_alphanumeric()}'
    with update(host, from_details=True):
        host.custom_ident = new_custom_id
    assert navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier') == new_custom_id
    try:
        existing_custom_id = navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier')
    except NameError:
        existing_custom_id = None
    new_custom_id = f'Edit host data. {fauxfactory.gen_alphanumeric()}'
    with update(host, from_details=True, cancel=True):
        host.custom_ident = new_custom_id
    try:
        assert navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier') == existing_custom_id
    except NameError:
        if existing_custom_id:
            raise
    view = navigate_to(host, 'Edit')
    try:
        view.navigation.select('Compute', 'Infrastructure', 'Hosts', handle_alert=False)
    except UnexpectedAlertPresentException as e:
        if 'Abandon changes' in e.msg:
            pytest.fail('Abandon changes alert displayed, but no changes made. BZ1634794')
        else:
            raise
    view = host.create_view(HostsView)
    assert view.is_displayed
    try:
        assert navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier') == existing_custom_id
    except NameError:
        if existing_custom_id:
            raise
    new_custom_id = f'Edit host data. {fauxfactory.gen_alphanumeric()}'
    view = navigate_to(host, 'Edit')
    view.fill({'custom_ident': new_custom_id})
    view = navigate_to(host.parent, 'All')
    assert view.is_displayed
    try:
        assert navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier') == existing_custom_id
    except NameError:
        if existing_custom_id:
            raise
    host.delete(cancel=True)
    host.delete

def purestr(x):
    if not isinstance(x, Basic):
        return str(x)
    return srepr(x)

def __gpt_labeldisk(self, type, devname, label=''):
    self.__system('dd if=/dev/zero of=/dev/%s bs=1m count=1' % devname)
    self.__system("dd if=/dev/zero of=/dev/%s bs=1m oseek=`diskinfo %s | awk '{print ($3 / (1024*1024)) - 3;}'`" % (devname, devname))
    self.__system('dd if=/dev/zero of=/dev/%s bs=4096 count=1' % devname)
    self.__system("dd if=/dev/zero of=/dev/%s bs=4096 oseek=`diskinfo %s | awk '{print ($3 / (4096)) - 3;}'`" % (devname, devname))
    if label != '':
        self.__system('gpart create -s gpt /dev/%s && gpart add -t %s -l %s %s' % (devname, type, label, devname))
    else:
        self.__system('gpart create -s gpt /dev/%s && gpart add -t %s %s' % (devname, type, devname))

def __gpt_labeldisk(self, type, devname, label=''):
    self.__system('dd if=/dev/zero of=/dev/%s bs=1m count=1' % devname)
    self.__system("dd if=/dev/zero of=/dev/%s bs=1m oseek=`diskinfo %s | awk '{print ($3 / (1024*1024)) - 3;}'`" % (devname, devname))
    if label != '':
        self.__system('gpart create -s gpt /dev/%s && gpart add -t %s -l %s %s' % (devname, type, label, devname))
    else:
        self.__system('gpart create -s gpt /dev/%s && gpart add -t %s %s' % (devname, type, devname))

def __new__(cls, class_name, bases, class_dict):
    names = []
    names_with_refs = []
    includes = {}
    removes = []
    for (name, prop) in class_dict.iteritems():
        if not isinstance(prop, Include):
            continue
        delegate = prop._delegate
        if not (isinstance(delegate, type) and issubclass(delegate, PropertyGroup)):
            continue
        if prop._prefix is None:
            prefix = name + '_'
        else:
            prefix = prop._prefix + '_'
        for subpropname in dir(delegate):
            if subpropname.startswith('__'):
                continue
            fullpropname = prefix + subpropname
            subprop = getattr(delegate, subpropname)
            if isinstance(subprop, BaseProperty):
                subprop = copy(subprop)
            includes[fullpropname] = subprop
        removes.append(name)
    for (key, val) in includes.iteritems():
        if key not in class_dict:
            class_dict[key] = val
    for tmp in removes:
        del class_dict[tmp]
    for (name, prop) in class_dict.iteritems():
        if isinstance(prop, BaseProperty):
            prop.name = name
            if hasattr(prop, 'has_ref') and prop.has_ref:
                names_with_refs.append(name)
            names.append(name)
        elif isinstance(prop, type) and issubclass(prop, BaseProperty):
            newprop = prop.autocreate(name=name)
            class_dict[name] = newprop
            newprop.name = name
            names.append(name)
    class_dict['__properties__'] = names
    class_dict['__properties_with_refs__'] = names_with_refs
    return type.__new__(cls, class_name, bases, class_dict)

