def on_change_completed_part(self, newtext):
    text = self.text()
    cursor_position = self.cursorPosition()
    if text[0] in STARTCHARS:
        prefix = text[0]
        text = text[1:]
    else:
        prefix = ''
    parts = split_cmdline(text)
    logger.debug("Old text: '{}' - parts: {}, changing to '{}'".format(text, parts, newtext))
    if cursor_position > 0:
        part_index = len(parts) - 1
        for (i, part) in enumerate(parts):
            if sum((len(p) + 1 for p in parts[:i])) + len(part) >= cursor_position:
                part_index = i
                break
        parts[part_index] = newtext
    else:
        parts[-1] = newtext
    self.setText(prefix + ' '.join(parts))
    self.setFocus()
    self.show_cmd.emit()

