import jsonschema
from jsonschema import validate

class FRSW:
    request_schema = {'type': 'object', 'properties': {'id': {'type': 'string'}, 'port_id': {'type': 'string'}}, 'required': ['id', 'port_id']}

    def frsw_allocate_udp_port(self, request):
        if request is None:
            self.send_param_error()
            return
        try:
            validate(instance=request, schema=self.request_schema)
        except jsonschema.exceptions.ValidationError as e:
            self.send_custom_error(f'Invalid request: {e.message}')
            return
        log.debug('received request {}'.format(request))
        frsw_id = request['id']
        if frsw_id not in self._frame_relay_switches:
            self.send_custom_error("Frame relay switch id {} doesn't exist".format(frsw_id))
            return
        frsw = self._frame_relay_switches[frsw_id]
        try:
            response = self.allocate_udp_port(frsw)
        except DynamipsError as e:
            self.send_custom_error(str(e))
            return
        response['port_id'] = request['port_id']
        self.send_response(response)

def frsw_allocate_udp_port(self, request):
    if request is None:
        self.send_param_error()
        return
    if 'id' not in request or 'port_id' not in request:
        self.send_custom_error('Missing mandatory parameters: id and port_id.')
        return
    log.debug('received request {}'.format(request))
    frsw_id = request['id']
    if frsw_id not in self._frame_relay_switches:
        self.send_custom_error("Frame relay switch id {} doesn't exist".format(frsw_id))
        return
    frsw = self._frame_relay_switches[frsw_id]
    try:
        response = self.allocate_udp_port(frsw)
    except DynamipsError as e:
        self.send_custom_error(str(e))
        return
    response['port_id'] = request['port_id']
    self.send_response(response)

def test_cmdline(self):
    self.proc = subprocess.Popen([PYTHON, '-E'], stdout=DEVNULL, stderr=DEVNULL)
    while True:
        try:
            psutil.Process(self.proc.pid)
            break
        except psutil.NoSuchProcess:
            time.sleep(0.01)
    self.assertEqual(psutil.Process(self.proc.pid).cmdline(), [PYTHON, '-E'])

def test_cmdline(self):
    self.proc = subprocess.Popen([PYTHON, '-E'], stdout=DEVNULL, stderr=DEVNULL)
    while True:
        try:
            if psutil.Process(self.proc.pid).is_running():
                break
        except psutil.NoSuchProcess:
            continue
    self.assertEqual(psutil.Process(self.proc.pid).cmdline(), [PYTHON, '-E'])

def condense_to_fragments(self, property, fragments, w_power=1):
    if not self.validate_fragments(fragments):
        raise ValueError('Invalid fragments provided.')
    if fragments is None:
        fragments = [[index] for index in range(self.part.natom)]
    condensed = np.zeros(len(fragments))
    for (index, frag) in enumerate(fragments):
        weight = np.zeros(self.grid.points.shape[0])
        for item in frag:
            weight += self.part.cache.load('at_weights', item)
        share = self.grid.integrate(weight ** w_power, property)
        condensed[index] = share
    return condensed

def validate_fragments(self, fragments):
    if not isinstance(fragments, list):
        return False
    for frag in fragments:
        if not isinstance(frag, list) or not all((isinstance(i, int) for i in frag)):
            return False
    return True

def condense_to_fragments(self, property, fragments, w_power=1):
    if fragments is None or len(fragments) == 0:
        fragments = [[index] for index in range(self.part.natom)]
    condensed = np.zeros(len(fragments))
    for (index, frag) in enumerate(fragments):
        weight = np.zeros(self.grid.points.shape[0])
        for item in frag:
            weight += self.part.cache.load('at_weights', item)
        share = self.grid.integrate(weight ** w_power, property)
        condensed[index] = share
    return condensed

def maintain_process_mapping(self):
    import time, subprocess
    while self.device.is_connected:
        ps_out = subprocess.check_output(['adb', 'shell', 'ps']).decode('utf-8')
        for line in ps_out.split('\n')[1:-1]:
            parts = line.split()
            if len(parts) >= 9:
                pid = parts[1]
                uid = parts[0]
                name = ' '.join(parts[8:])
                self.pid2uid[pid] = uid
                self.pid2name[pid] = name
        time.sleep(1)

def zeros_like(a, dtype=None, order='C', subok=True):
    if dtype is None:
        dtype = a.dtype
    a = cupy.ndarray(a.shape, dtype, order=order, subok=subok)
    a.data.memset_async(0, a.nbytes)
    return a

def zeros_like(a, dtype=None, order='C'):
    if dtype is None:
        dtype = a.dtype
    a = cupy.ndarray(a.shape, dtype=dtype, order=order)
    a.data.memset_async(0, a.nbytes)
    return a

def _call(self, method, *args, **kwargs):
    tid = self._tid.next()
    msg = {'method': method, 'params': list(args)}
    is_notify = '_notify' in kwargs
    if not is_notify:
        msg['id'] = tid
    msg = json.dumps(msg)
    for timeout in self._service.iter_rpc_retry_timeout():
        services = self._service.resolve_service(self._service_name)
        if not services:
            raise RPCError('Service not found')
        for svc in services:
            client = tornado.httpclient.AsyncHTTPClient()
            try:
                response = (yield client.fetch('http://%s/api/%s/' % (svc, self._api), method='POST', body=msg))
            except tornado.httpclient.HTTPError as why:
                if why.code != 499:
                    raise RPCError('RPC Call Failed: %s', why)
                else:
                    self._service.logger.info('Service is not available at %s. Retrying', svc)
                    continue
            except tornado.netutil.ConnectionRefusedError:
                self._service.logger.error('Connection refused when trying to reach %s. Retrying', svc)
                continue
            except Exception as why:
                raise RPCError('RPC Call Failed: %s' % why)
            if not is_notify:
                result = json.loads(response.body)
                if result.get('error'):
                    raise RPCError('RPC Call Failed: %s' % result['error'])
                else:
                    raise tornado.gen.Return(result['result'])
        self._service.logger.info('All services are not available. Waiting %s seconds')
        yield tornado.gen.sleep(timeout)

