def update(self, req, node_id, body):
    node_data = body.get('node')
    if node_data is None:
        raise exc.HTTPBadRequest(_("Malformed request data, missing'node' key in request body."))
    data = NodeData(node_data)
    updatable_fields = ['name', 'profile_id', 'role', 'tags']
    updates = {field: getattr(data, field)() for field in updatable_fields if hasattr(data, field) and data.__getattribute__(field)() is not None}
    if 'join' in node_data or 'leave' in node_data:
        pass
    self.rpc_client.node_update(req.context, node_id, **updates)
    raise exc.HTTPAccepted()

def update(self, req, node_id, body):
    node_data = body.get('node')
    if node_data is None:
        raise exc.HTTPBadRequest(_("Malformed request data, missing'node' key in request body."))
    updatable_fields = ['name', 'profile_id', 'role', 'tags']
    for field in updatable_fields:
        if field not in node_data:
            raise exc.HTTPBadRequest(_('Missing updatable field: %s' % field))
    data = NodeData(node_data)
    if 'join' in node_data or 'leave' in node_data:
        pass
    self.rpc_client.node_update(req.context, node_id, data.name(), data.profile_id(), data.role(), data.tags())
    raise exc.HTTPAccepted()

