    return {'rname': lambda x, m=tIdMap: m[x.tId], 'length': lambda x: x.aEnd - x.aStart, 'qname': lambda x: x.qId, 'zm': lambda x: x.holeNumber, 'pos': lambda x: x.tStart, 'readstart': lambda x: x.aStart, 'tstart': lambda x: self._get_overlapping_start(x), 'tend': lambda x: self._get_overlapping_end(x)}

def _get_overlapping_start(self, x):
    return x.tStart

def _get_overlapping_end(self, x):
    return x.tEnd

def _create_product(self, metadata_type, product_type, data_measurements, storage, stats_metadata, custom_metadata):
    product_definition = {'name': self.name, 'description': 'Description for ' + self.name, 'metadata_type': metadata_type.name, 'metadata': {'product_type': product_type, 'statistics': stats_metadata, **custom_metadata}, 'storage': storage, 'measurements': data_measurements}
    Product.validate(product_definition)
    return Product(metadata_type, product_definition)

def create_source_container_build(self, sources_for_koji_build_nvr=None, outer_template=None, arrangement_version=None, scratch=None, signing_intent=None, user=None, platform=None, koji_task_id=None, reactor_config_override=None, target=None):
    build_request = self.get_source_container_build_request(outer_template=outer_template or ORCHESTRATOR_SOURCES_OUTER_TEMPLATE, arrangement_version=arrangement_version)
    if not sources_for_koji_build_nvr:
        raise OsbsValidationException("required argument 'sources_for_koji_build_nvr' can't be None")
    (name, _, _) = sources_for_koji_build_nvr.split('-', 3)
    if not name or not isinstance(name, str):
        raise OsbsValidationException('Invalid component name extracted from sources_for_koji_build_nvr')
    build_request.set_params(arrangement_version=arrangement_version, component=name, build_image=self.build_conf.get_build_image(), build_imagestream=self.build_conf.get_build_imagestream(), build_from=self.build_conf.get_build_from(), builder_build_json_dir=self.build_conf.get_builder_build_json_store(), koji_target=target, koji_task_id=koji_task_id, orchestrator_deadline=self.build_conf.get_orchestor_deadline(), platform=platform, reactor_config_map=self.build_conf.get_reactor_config_map(), reactor_config_override=reactor_config_override, scratch=self.build_conf.get_scratch(scratch), signing_intent=signing_intent, sources_for_koji_build_nvr=sources_for_koji_build_nvr, user=user, worker_deadline=self.build_conf.get_worker_deadline())
    build_request.set_openshift_required_version(self.os_conf.get_openshift_required_version())
    builds_for_koji_task = []
    if koji_task_id:
        builds_for_koji_task = self._get_not_cancelled_builds_for_koji_task(koji_task_id)
    builds_count = len(builds_for_koji_task)
    if builds_count == 1:
        logger.info('found running build for koji task: %s', builds_for_koji_task[0].get_build_name())
        response = BuildResponse(self.os.get_build(builds_for_koji_task[0].get_build_name()).json(), self)
    elif builds_count > 1:
        raise OsbsException('Multiple builds %s for koji task id %s' % (builds_count, koji_task_id))
    else:
        logger.info('creating source container image build')
        response = self._create_build_directly(build_request)
    logger.debug(response.json)
    return response

def logMsg(title, msg, level=1):
    logLevel = get_log_level()
    if logLevel >= level:
        if logLevel == 1:
            try:
                xbmc.log(title + ' -> ' + inspect.stack()[1][3] + ' : ' + str(msg))
            except UnicodeEncodeError:
                xbmc.log(title + ' -> ' + inspect.stack()[1][3] + ' : ' + str(msg.encode('utf-8')))
        else:
            try:
                xbmc.log(title + ' -> ' + str(msg))
            except UnicodeEncodeError:
                xbmc.log(title + ' -> ' + str(msg.encode('utf-8')))

