import re
from typing import List

def extract_products(text: str) -> List[str]:
    regex = '\\b[A-Z][a-zA-Z0-9&\\s-]*[A-Za-z]\\b'
    result = set(re.findall(regex, text))
    return sorted([p.strip() for p in result if len(p.strip()) > 2])

