            for line in fd:
                if line.startswith('ArrayDesc('):
                    m = re.match(".*\\((\\d+),\\s*(\\d+)\\).*dtype\\(\\'\\'(.*)\\'\\'\\).*", line)
                    if m:
                        (nx, ny) = (int(m.group(1)), int(m.group(2)))
                        dtype = m.group(3)
                        return np.fromfile(filename, dtype).reshape((ny, nx))
            raise NicosError('no ArrayDesc line found')
    else:
        raise NicosError('file and/or corresponding .header not found')

def translate_nd(self, source: mx.nd.NDArray, source_length: mx.nd.NDArray, bucket_key: int) -> Tuple[np.ndarray, np.ndarray, float]:
    max_output_length = min(source_length * 2, bucket_key * C.TARGET_MAX_LENGTH_FACTOR)
    return self._get_best_from_beam(*self._beam_search(source, source_length, bucket_key, max_output_length))

def S1s(self, sort_key='area', reverse=True, tpc_only=False, veto=False):
    peaks = self._get_peaks_by_type('s1', sort_key, reverse)
    if tpc_only:
        peaks = [peak for peak in peaks if peak.is_tpc]
    if veto:
        peaks = [peak for peak in peaks if not peak.is_veto]
    return peaks

def _preprocess(self, dataset, fit=False):
    blocks_by_depth = []
    remaining_blocks = set(self._blocks)
    depth_count = 0
    while remaining_blocks:
        temp_blocks = []
        for block in list(remaining_blocks):
            if all((self._node_to_id[input_node] in self._node_to_id for input_node in block.inputs)):
                temp_blocks.append(block)
        if not temp_blocks:
            break
        blocks_by_depth.append(temp_blocks)
        for block in temp_blocks:
            remaining_blocks.remove(block)
        depth_count += 1
    input_node_ids = [self._node_to_id[input_node] for input_node in self.inputs]
    for blocks in blocks_by_depth:
        if fit:
            for (x, y) in dataset:
                x = nest.flatten(x)
                node_id_to_data = {node_id: temp_x for (temp_x, node_id) in zip(x, input_node_ids)}
                for block in blocks:
                    data = [node_id_to_data[self._node_to_id[input_node]] for input_node in block.inputs]
                    block.update(data, y=y)
            for block in blocks:
                block.finalize()
                nest.flatten(block.outputs)[0].shape = block.output_shape
        dataset = dataset.map(functools.partial(self._preprocess_transform, input_node_ids=input_node_ids, blocks=blocks, fit=fit))
        input_node_ids = list(sorted([self._node_to_id[block.outputs[0]] for block in blocks]))
    return dataset

def _preprocess(self, dataset, fit=False):
    blocks_by_depth = []
    remaining_blocks = set(self._blocks)
    depth_count = 0
    while remaining_blocks:
        temp_blocks = []
        for block in remaining_blocks:
            if all((input_node in self._node_to_id for input_node in block.inputs)):
                temp_blocks.append(block)
        if not temp_blocks:
            break
        blocks_by_depth.append(temp_blocks)
        for block in temp_blocks:
            self._add_block(block)
            remaining_blocks.remove(block)
            self._block_topo_depth[self._block_to_id[block]] = depth_count
        depth_count += 1
    self._total_topo_depth = depth_count
    input_node_ids = [self._node_to_id[input_node] for input_node in self.inputs]
    for blocks in blocks_by_depth:
        if fit:
            for (x, y) in dataset:
                x = nest.flatten(x)
                node_id_to_data = {node_id: temp_x for (temp_x, node_id) in zip(x, input_node_ids)}
                for block in blocks:
                    data = [node_id_to_data[self._node_to_id[input_node]] for input_node in block.inputs]
                    block.update(data, y=y)
            for block in blocks:
                block.finalize()
                nest.flatten(block.outputs)[0].shape = block.output_shape
        dataset = dataset.map(functools.partial(self._preprocess_transform, input_node_ids=input_node_ids, blocks=blocks, fit=fit))
        input_node_ids = list(sorted([self._node_to_id[block.outputs[0]] for block in blocks]))
    return dataset

