def string_contents(self):
    try:
        return ast.literal_eval(self.text)
    except (ValueError, SyntaxError) as e:
        raise ValueError(f'Invalid literal for evaluation: {self.text}') from e

def set(self, item, value):
    if value.ndim == self.ndim - 1:
        value = value.reshape((1,) + value.shape)
    assert value.shape[1:] == self.shape[1:]
    if item in self.items:
        (i, block) = self._find_block(item)
        if not block.can_store(value):
            self._delete_from_block(i, item)
            self._add_new_block(item, value)
        else:
            block.set(item, value)
    else:
        loc = len(self.items)
        new_items = _insert_into_columns(self.items, item, loc)
        self.set_items_norename(new_items)
        self._add_new_block(item, value)

def process_transaction(self, data: bytes):
    if not self.__validate_transaction_length(data):
        return {'error': TX_STATUS['INVALID_TX_SIZE']}
    try:
        d = self.serializer.deserialize(data)
    except Exception as e:
        return {'error': TX_STATUS['SERIALIZE_FAILED'].format(e)}
    try:
        TestNetTransaction.validate_tx_fields(d)
    except Exception as e:
        return {'error': TX_STATUS['INVALID_TX_FIELDS'].format(e)}
    d['metadata']['timestamp'] = time.time()
    d['metadata']['uuid'] = str(uuid.uuid4())
    from cilantro.wallets.ed25519 import ED25519Wallet
    payload_binary = JSONSerializer.serialize(d['payload'])
    if not ED25519Wallet.verify(d['payload']['from'], payload_binary, d['metadata']['signature']):
        return {'error': TX_STATUS['INVALID_SIGNATURE']}
    return self.publish_req(d)

def claimMahJongg(self, player, concealedMelds, withDiscard):
    melds = []
    for part in concealedMelds.split():
        meld = Meld(part)
        melds.append(meld)
        for pair in meld.pairs:
            if pair not in player.concealedTiles:
                print('concealedMelds:', concealedMelds)
                print('meld:', meld)
                print('tile:', pair)
                msg = 'claimMahJongg: Player does not really have tile %s' % pair
                self.sendAbortMessage(msg)
                return
    ignoreDiscard = withDiscard
    for meld in melds:
        for pair in meld.pairs:
            if pair == ignoreDiscard:
                ignoreDiscard = None
            else:
                player.concealedTiles.remove(pair)
        player.concealedMelds.append(meld)
    if player.concealedTiles:
        msg = 'claimMahJongg: Player did not pass all concealed tiles to server'
        self.sendAbortMessage(msg)
        return
    self.game.winner = player
    self.tellAll(player, 'declaredMahJongg', source=concealedMelds, lastTile=player.lastTile, withDiscard=withDiscard)
    self.endHand()

def remove_voided_by(self, tx: Transaction, voided_hash: bytes) -> bool:
    from hathor.transaction.storage.traversal import BFSWalk
    assert tx.hash is not None
    assert tx.storage is not None
    meta = tx.get_metadata()
    if not meta.voided_by:
        return False
    if voided_hash not in meta.voided_by:
        return False
    self.log.debug('remove_voided_by', tx=tx.hash_hex, voided_hash=voided_hash.hex())
    bfs = BFSWalk(tx.storage, is_dag_funds=True, is_dag_verifications=True, is_left_to_right=True)
    check_list: List[BaseTransaction] = []
    for tx2 in bfs.run(tx, skip_root=False):
        assert tx2.storage is not None
        meta = tx2.get_metadata()
        if not (meta.voided_by and voided_hash in meta.voided_by):
            bfs.skip_neighbors(tx2)
            continue
        if meta.voided_by:
            meta.voided_by.discard(voided_hash)
        if meta.voided_by == {tx2.hash}:
            check_list.append(tx2)
        tx2.storage.save_transaction(tx2, only_metadata=True)
        if not meta.voided_by:
            meta.voided_by = None
            tx.storage.add_to_cache(tx2)
    from hathor.transaction import Transaction
    for tx2 in check_list:
        if not tx2.is_block:
            assert isinstance(tx2, Transaction)
            self.check_conflicts(tx2)
    return True

def __call__(self, data, **kwargs):
    columnIndex = self._get_columnIndex(data)
    is_multiLevel = isinstance(data, MultilevelParquetTable) or isinstance(columnIndex, pd.MultiIndex)
    if isinstance(data, ParquetTable) and (not is_multiLevel):
        columns = self.columns
        df = data.toDataFrame(columns=columns)
        valDict = {k: f._func(df) for (k, f) in self.funcDict.items()}
    elif is_multiLevel:
        columns = self.multilevelColumns(data, columnIndex=columnIndex)
        if isinstance(data, MultilevelParquetTable):
            df = data.toDataFrame(columns=columns, droplevels=False)
        elif isinstance(data, DeferredDatasetHandle):
            df = data.get(parameters={'columns': columns})
        valDict = {}
        for (k, f) in self.funcDict.items():
            try:
                subdf = f._setLevels(df[f.multilevelColumns(data, returnTuple=True, columnIndex=columnIndex)])
                valDict[k] = f._func(subdf)
            except Exception:
                valDict[k] = f.fail(subdf)
    elif isinstance(data, DeferredDatasetHandle):
        columns = self.columns
        df = data.get(parameters={'columns': columns})
        valDict = {k: f._func(df) for (k, f) in self.funcDict.items()}
    try:
        valDf = pd.concat(valDict, axis=1)
    except TypeError:
        print([(k, type(v)) for (k, v) in valDict.items()])
        raise
    if kwargs.get('dropna', False):
        valDf = valDf.dropna(how='any')
    return valDf

def _generate_data_key_pair(data):
    key_id = data.get('KeyId')
    rsa_key_sizes = {'RSA_2048': 2048, 'RSA_3072': 3072, 'RSA_4096': 4096}
    ecdsa_key_sizes = {'ECDSA_P256': 256, 'ECDSA_P384': 384, 'ECDSA_P521': 521}
    key_spec = data['KeyPairSpec']
    key_size = rsa_key_sizes.get(key_spec) or ecdsa_key_sizes.get(key_spec)
    if not key_size:
        LOG.warning("Unsupported KeyPairSpec specified to generate key pair: '%s'", key_spec)
        raise ValueError(f'Unsupported KeyPairSpec: {key_spec}')
    if key_spec.startswith('RSA'):
        key = rsa.generate_private_key(public_exponent=65537, key_size=key_size)
    elif key_spec.startswith('ECDSA'):
        key = ec.generate_private_key(ec.SECP256R1() if key_spec == 'ECDSA_P256' else ec.SECP384R1() if key_spec == 'ECDSA_P384' else ec.SECP521R1())
    else:
        raise ValueError(f'Unsupported KeyPairSpec: {key_spec}')
    private_key = key.private_bytes(crypto_serialization.Encoding.DER, crypto_serialization.PrivateFormat.PKCS8, crypto_serialization.NoEncryption())
    public_key = key.public_key().public_bytes(crypto_serialization.Encoding.DER, crypto_serialization.PublicFormat.SubjectPublicKeyInfo)
    kms = aws_stack.connect_to_service('kms')
    cipher_text = kms.encrypt(KeyId=key_id, Plaintext=private_key)['CiphertextBlob']
    result = {'PrivateKeyCiphertextBlob': base64.b64encode(cipher_text), 'PrivateKeyPlaintext': base64.b64encode(private_key), 'PublicKey': base64.b64encode(public_key), 'KeyId': key_id, 'KeyPairSpec': data.get('KeyPairSpec')}
    key_pairs = _get_key_pairs()
    key_pairs[key_id] = result
    return result

def get(self, request: Request, project, version) -> Response:
    organization_id = project.organization_id
    try:
        release = Release.objects.get(organization_id=organization_id, projects=project, version=version)
    except Release.DoesNotExist:
        raise ResourceDoesNotExist
    queryset = ReleaseCommit.objects.filter(release=release).select_related('commit', 'commit__author')
    repo_id = request.query_params.get('repo_id')
    if repo_id:
        try:
            repo = Repository.objects.get(organization_id=organization_id, id=repo_id, status=ObjectStatus.ACTIVE)
            queryset = queryset.filter(commit__repository_id=repo.id)
        except Repository.DoesNotExist:
            raise ResourceDoesNotExist
    return self.paginate(request=request, queryset=queryset, order_by='order', on_results=lambda x: serialize([rc.commit for rc in x], request.user))

def get(self, request):
    installed_apps = {}
    for app_config in apps.get_app_configs():
        app = app_config.module
        version = getattr(app, 'VERSION', getattr(app, '__version__', None))
        if version:
            if isinstance(version, tuple):
                version = '.'.join((str(n) for n in version))
        installed_apps[app_config.name] = version
    installed_apps = dict(sorted(installed_apps.items()))
    plugins = {}
    for plugin_name in settings.PLUGINS:
        plugin_name = plugin_name.rsplit('.', 1)[-1]
        plugin_config = apps.get_app_config(plugin_name)
        plugins[plugin_name] = getattr(plugin_config, 'version', None)
    plugins = dict(sorted(plugins.items()))
    workers = celery_app.control.inspect().active()
    worker_count = len(workers) if workers is not None else 0
    return Response({'django-version': DJANGO_VERSION, 'installed-apps': installed_apps, 'nautobot-version': settings.VERSION, 'plugins': plugins, 'python-version': platform.python_version(), 'celery-workers-running': worker_count})

