class Report:

    def create_report_if_not_exists_from_external_reference(self, external_reference_id, name, description, published, report_class, object_status=None, source_confidence_level=None, graph_data=None, id=None, stix_id_key=None, created=None, modified=None):
        object_result = self.read(filters=[{'key': 'hasExternalReference', 'values': [external_reference_id]}])
        if object_result is not None:
            return object_result
        else:
            report = self.create_report(name, description, published, report_class, object_status, source_confidence_level, graph_data, id, stix_id_key, created, modified)
            self.add_external_reference(id=report['id'], external_reference_id=external_reference_id)
            return report

class OpenCTIApiClient:

    def __init__(self, url, token, log_level='info', ssl_verify=False):
        self.report = Report(self)

class OpenCTIApiClient:

    def create_report_if_not_exists_from_external_reference(self, external_reference_id, name, description, published, report_class, object_status=None, source_confidence_level=None, graph_data=None, id=None, stix_id_key=None, created=None, modified=None):
        object_result = self.report.read(filters=[{'key': 'hasExternalReference', 'values': [external_reference_id]}])
        if object_result is not None:
            return object_result
        else:
            report = self.create_report(name, description, published, report_class, object_status, source_confidence_level, graph_data, id, stix_id_key, created, modified)
            self.stix_entity.add_external_reference(id=report['id'], external_reference_id=external_reference_id)
            return report

    def create_report(self, name, description, published, report_class, object_status=None, source_confidence_level=None, graph_data=None, id=None, stix_id_key=None, created=None, modified=None):
        logging.info('Creating report ' + name + '...')
        query = '\n           mutation ReportAdd($input: ReportAddInput) {\n               reportAdd(input: $input) {\n                   id\n                   entity_type\n                   alias\n               }\n           }\n        '
        result = self.query(query, {'input': {'name': name, 'description': description, 'published': published, 'report_class': report_class, 'object_status': object_status, 'source_confidence_level': source_confidence_level, 'graph_data': graph_data, 'internal_id_key': id, 'stix_id_key': stix_id_key, 'created': created, 'modified': modified}})
        return result['data']['reportAdd']

async def save_content(request: Request, user: UserRead=Depends(current_user)):
    save_content = SaveContent(**await request.json())
    try:
        async with await open_file(save_content.path, 'w') as f:
            if save_content.format == 'json':
                dict_content = cast(Dict, save_content.content)
                if save_content.type == 'notebook':
                    if 'metadata' in dict_content and 'orig_nbformat' in dict_content['metadata']:
                        del dict_content['metadata']['orig_nbformat']
                await f.write(json.dumps(dict_content, indent=2))
            else:
                str_content = cast(str, save_content.content)
                await f.write(str_content)
    except Exception as e:
        return JSONResponse(content={'error': str(e)}, status_code=500)
    return Content(**await get_path_content(Path(save_content.path), False))

def refresh(self, list_aged: Set[Tuple[str, str, int]]):
    provider = self.plcy_provider
    for o in list_aged:
        if o[0] == provider.PORT:
            self.callback(o[1], self.port)
        elif o[0] == provider.QOS:
            self.callback(o[1], self.qos)
        elif o[0] == provider.SG_RULES:
            self.callback(o[1], self.security_group_rules)
        elif o[0] == provider.SG_MEMBERS:
            self.callback(o[1], self.security_group_members)

def count_and_checksum(self) -> Tuple[int, int]:
    start = time.time()
    (count, checksum) = self.database.query(self._make_select(columns=[Count(), Checksum(self._relevant_columns)]), tuple)
    duration = time.time() - start
    if duration > RECOMMENDED_CHECKSUM_DURATION:
        logger.warn(f'Checksum is taking longer than expected ({duration:.2f}s). We recommend increasing the bisection-factor.')
    count = count if count is not None else 0
    checksum = checksum if checksum is not None else 0
    return (count, checksum)

def set_subject(self, room_jid, subject):
    self.subjects[room_jid] = subject
    name_label = self.name_labels[room_jid]
    full_subject = None
    if gtk.gtk_version < (2, 6, 0) or gtk.pygtk_version < (2, 6, 0):
        if len(subject) > 80:
            full_subject = subject
            subject = subject[:77] + '...'
        if subject.count('\n') > 1:
            subject = '\n'.join(subject.split('\n')[:2]) + '...'
    subject = gtkgui_helpers.escape_for_pango_markup(subject)
    name_label.set_markup('<span weight="heavy" size="x-large">%s</span>\n%s' % (room_jid, subject))
    event_box = name_label.get_parent()
    if subject == '':
        subject = _('This room has no subject')
    if full_subject is not None:
        subject = full_subject
    self.subject_tooltip[room_jid].set_tip(event_box, subject)

def continuous_migration():
    indexer = RecordIndexer()
    redis_url = current_app.config.get('CACHE_REDIS_URL')
    r = StrictRedis.from_url(redis_url)
    try:
        while r.llen('legacy_records'):
            raw_record = r.lpop('legacy_records')
            if raw_record:
                raw_record = zlib.decompress(raw_record)
                record = migrate_and_insert_record(raw_record)
                if record is None:
                    continue
                indexer.index_by_id(record.id)
    finally:
        db.session.commit()
        db.session.close()

def is_rank_in_embedding_group(ignore_virtual=False):
    rank = torch.distributed.get_rank()
    global _EMBEDDING_GLOBAL_RANKS
    if ignore_virtual:
        return rank in _EMBEDDING_GLOBAL_RANKS
    if rank in _EMBEDDING_GLOBAL_RANKS:
        if rank == _EMBEDDING_GLOBAL_RANKS[0]:
            return is_pipeline_first_stage(ignore_virtual=False)
        elif rank == _EMBEDDING_GLOBAL_RANKS[-1]:
            return is_pipeline_last_stage(ignore_virtual=False)
        else:
            return True
    return False

