def create_temp_user_avatar(self, user, filename, size, avatar_img, contentType=None, auto_confirm=False):
    if size is None:
        avatar_img.seek(0)
        with Image.open(avatar_img) as img:
            size = img.size
    params = {'username': user, 'filename': filename, 'size': size}
    headers = {'X-Atlassian-Token': 'no-check'}
    if contentType is not None:
        headers['content-type'] = contentType
    else:
        headers['content-type'] = self._get_mime_type(avatar_img)
    url = self._get_url('user/avatar/temporary')
    r = self._session.post(url, params=params, headers=headers, data=avatar_img)
    raise_on_error(r)
    cropping_properties = json.loads(r.text)
    if auto_confirm:
        return self.confirm_user_avatar(user, cropping_properties)
    else:
        return cropping_properties

def termdef(term):
    types = set((o.id for o in term.objects(RDF.type)))
    is_class = types & CLASS_TYPES
    is_prop = types & PROP_TYPES
    if not is_class and (not is_prop):
        return None
    if is_class:
        equiv = OWL.equivalentClass
        subof = RDFS.subClassOf
    else:
        equiv = OWL.equivalentProperty
        subof = RDFS.subPropertyOf
    target_candidates = [term.value(OWL.sameAs), term.value(equiv), term.value(subof)]
    target_term = next((candidate for candidate in target_candidates if candidate is not None), None)
    curie = unicode((target_term or term).qname())
    if is_class:
        return curie
    range_type = term.value(RDFS.range)
    range_iri = range_type and range_type.id
    if range_iri and range_iri.startswith(XSD) or range_iri == RDFS.Literal:
        datatype = range_type.qname()
    elif OWL.DatatypeProperty in types:
        datatype = False
    else:
        datatype = None
    if types & {RDF.Property, OWL.FunctionalProperty}:
        container = None
    elif range_iri == RDF.List:
        container = '@list'
    else:
        container = None
    reverse = None if target_term else term.value(OWL.inverseOf)
    if reverse or datatype or container:
        if reverse:
            dfn = {'@reverse': unicode(reverse.qname())}
        else:
            dfn = {'@id': curie}
        if datatype:
            dfn['@type'] = datatype
        elif datatype is False:
            dfn['@language'] = None
        if container:
            dfn['@container'] = container
        return dfn
    else:
        return curie

