def cli(jail, name):
    """Get a list of jails and print the property."
    # This function should eventually be refactored to use an API for managing jails and snapshots.
    jails = ioc_list.IOCList("uuid").list_datasets()
    pool = ioc_json.IOCJson().json_get_value("pool")
    date = datetime.datetime.utcnow().strftime("%F_%T")
    _jail = {uuid: path for (uuid, path) in jails.items() if
             uuid.startswith(jail)}
    if len(_jail) == 1:
        uuid, path = next(iter(_jail.items()))
    elif len(_jail) > 1:
        ioc_common.logit({
            "level"  : "ERROR",
            "message": f"Multiple jails found for {jail}:"
        })
        for u, p in sorted(_jail.items()):
            ioc_common.logit({
                "level"  : "ERROR",
                "message": f"  {u} ({p})"
            })
        exit(1)
    else:
        ioc_common.logit({
            "level"  : "EXCEPTION",
            "message": f"{jail} not found!"
        }, exit_on_error=True)
    # If they don't supply a snapshot name, we will use the date.
    if not name:
        name = date
    # Looks like foo/iocage/jails/df0ef69a-57b6-4480-b1f8-88f7b6febbdf@BAR
    conf = ioc_json.IOCJson(path).json_load()
    if conf["template"] == "yes":
        target = f"{pool}/iocage/templates/{uuid}@{name}"
    else:
        target = f"{pool}/iocage/jails/{uuid}@{name}"
    try:
        su.check_call(["zfs", "snapshot", "-r", target], stderr=su.PIPE)
        ioc_common.logit({
            "level"  : "INFO",
            "message": f"Snapshot: {target} created."
        })
    except su.CalledProcessError:
        ioc_common.logit({
            "level"  : "EXCEPTION",
            "message": "Snapshot already exists!"
        }, exit_on_error=True)

def cutoffs(self) -> List[int]:
    if self._fock is None:
        return fock.autocutoffs(self.number_cov, self.number_means)
    else:
        return [s for s in self._fock.shape[:self.num_modes]]

def main():
    config.init()
    intents = discord.Intents.default()
    intents.guilds = True
    intents.members = True
    client = commands.Bot(config.prefix, intents=intents)
    for folder in os.listdir('modules'):
        if os.path.exists(os.path.join('modules', folder, 'cog.py')):
            client.load_extension(f'modules.{folder}.cog')

    @client.event
    async def on_message(message: discord.Message):
        await client.process_commands(message)

    @client.event
    async def on_ready():
        print(f'{client.user.name} has connected to Discord!')
    client.run(config.token)

def hook(self, repo_id=None, **post):
    if repo_id is None:
        json_data = post.get('json', {})
        ssh_url = json_data.get('repository', {}).get('ssh_url')
        repo = request.env['runbot.repo'].sudo().search([('ssh_url', '=', ssh_url)], limit=1)
    else:
        repo = request.env['runbot.repo'].sudo().browse([repo_id])
    repo.hook_time = datetime.datetime.now().strftime(tools.DEFAULT_SERVER_DATETIME_FORMAT)
    return ''

def store(self, kind: str, out: dict, storage) -> None:
    logger.debug(f'Storing BOLD in {storage}')
    storage.store_timeseries(**out)

def get_task_account_token(task_id, scopes):
    task_request = get_task_request_by_id(task_id)
    if not task_request:
        return ('none', None)
    service_account_email = task_request.service_account_email
    if service_account_email == 'bot':
        return ('bot', None)
    (blob, expiry) = auth.get_access_token(scopes=scopes, act_as=service_account_email, min_lifetime_sec=MIN_TOKEN_LIFETIME_SEC)
    assert isinstance(blob, str)
    assert isinstance(expiry, (int, float))
    token = AccessToken(blob, int(expiry))
    _check_and_log_token(service_account_email, token)
    return (service_account_email, token)

def copy_from_dict(self, dictionary, prefix=None):
    prefix = prefix or ''
    if prefix:
        with self._task._edit_lock:
            prefix_dictionary = dict([(prefix + k, v) for (k, v) in dictionary.items()])
            cur_params = dict([(k, v) for (k, v) in self._task.get_parameters().items() if not k.startswith(prefix)])
            cur_params.update(prefix_dictionary)
            self._task.set_parameters(cur_params)
    else:
        self._task.update_parameters(dictionary)
    if not isinstance(dictionary, self._ProxyDictWrite):
        return self._ProxyDictWrite(self, **dictionary)
    return dictionary

