def isvalid(self):
    entry = self['Desktop Entry']
    if 'Type' not in entry or entry['Type'] != 'Application':
        logger.error('"Type" missing or invalid')
        return False
    if 'Name' not in entry:
        logger.error('"Name" missing')
        return False
    if 'Exec' not in entry:
        logger.error('"Exec" missing')
        return False
    if 'Version' in entry and entry['Version'] != 1.0:
        logger.error('Version invalid')
        return False
    return True

def isvalid(self):
    entry = self['Desktop Entry']
    if 'Type' not in entry or entry['Type'] != 'Application':
        logger.exception('Invalid desktop entry: "Type" missing or invalid')
        return False
    if 'Name' not in entry:
        logger.exception('Invalid desktop entry: "Name" missing')
        return False
    if 'Exec' not in entry:
        logger.exception('Invalid desktop entry: "Exec" missing')
        return False
    if 'Version' in entry and entry['Version'] != 1.0:
        logger.exception('Invalid desktop entry: Version invalid')
        return False
    return True

def CMDcomments(parser, args):
    parser.add_option('-a', '--add-comment', dest='comment', help='comment to add to an issue')
    parser.add_option('-i', '--issue', dest='issue', help='review issue id (defaults to current issue). If given, requires --rietveld or --gerrit')
    parser.add_option('-j', '--json-file', help='File to write JSON summary to')
    auth.add_auth_options(parser)
    _add_codereview_select_options(parser)
    (options, args) = parser.parse_args(args)
    _process_codereview_select_options(parser, options)
    auth_config = auth.extract_auth_config_from_options(options)
    issue = None
    if options.issue:
        try:
            issue = int(options.issue)
        except ValueError:
            DieWithError('A review issue id is expected to be a number')
        if not options.forced_codereview:
            parser.error('--gerrit or --rietveld is required if --issue is specified')
    cl = Changelist(issue=issue, codereview=options.forced_codereview, auth_config=auth_config)
    if options.comment:
        cl.AddComment(options.comment)
        return 0
    summary = sorted(cl.GetCommentsSummary(), key=lambda c: c.date)
    for comment in summary:
        if comment.disapproval:
            color = Fore.RED
        elif comment.approval:
            color = Fore.GREEN
        elif comment.sender == cl.GetIssueOwner():
            color = Fore.MAGENTA
        else:
            color = Fore.BLUE
        print('\n%s%s   %s%s\n%s' % (color, comment.date.strftime('%Y-%m-%d %H:%M:%S UTC'), comment.sender, Fore.RESET, '\n'.join(('  ' + l for l in comment.message.strip().splitlines()))))
    if options.json_file:

        def pre_serialize(c):
            dct = c.__dict__.copy()
            dct['date'] = dct['date'].strftime('%Y-%m-%d %H:%M:%S.%f')
            return dct
        with open(options.json_file, 'wb') as f:
            json.dump(map(pre_serialize, summary), f)
    return 0

import json
import logging
import traceback

class ErrorCode:
    TRANSMISSION_UNKNOWN = 0
    TRANSMISSION_AUTH_SSL = 1
    TRANSMISSION_CONNECT = 2
    TRANSMISSION_AUTH_CREDENTIALS = 3
    TRANSMISSION_QUERY_PARSING_ERROR = 4

class ErrorMapperBase:

    @staticmethod
    def set_error_code(return_object, error_code):
        return_object['error_code'] = error_code

class ErrorResponder:
    logger = logging.getLogger(__name__)

    @staticmethod
    def get_struct_item(message_struct, message_path):
        if message_struct is not None and message_path is not None:
            if isinstance(message_struct, dict) or isinstance(message_struct, list):
                struct = message_struct.copy()
                for i in message_path:
                    if isinstance(struct, dict) and i in struct:
                        struct = struct[i]
                    elif isinstance(struct, list) and isinstance(i, int) and (i < len(struct)):
                        struct = struct[i]
                    else:
                        break
                return struct
            else:
                return message_struct

    @staticmethod
    def fill_error(return_object, message_struct=None, message_path=None, message=None, error=None):
        return_object['success'] = False
        error_code = ErrorCode.TRANSMISSION_UNKNOWN
        if message is None:
            message = ''
        struct_item = ErrorResponder.get_struct_item(message_struct, message_path)
        if struct_item is not None:
            if len(message) > 0:
                message += ';'
            if isinstance(struct_item, list):
                struct_item = json.dumps(struct_item)
            message += str(struct_item)
        error_msg = ''
        if error is not None:
            str_error = str(error)
            ErrorResponder.logger.error('Error occurred: %s', str_error, exc_info=True)
            if isinstance(error, SSLError):
                error_code = ErrorCode.TRANSMISSION_AUTH_SSL
                error_msg = 'Wrong certificate: ' + str_error
            elif isinstance(error, ConnectionError):
                error_code = ErrorCode.TRANSMISSION_CONNECT
                error_msg = 'Connection error: ' + str_error
            else:
                error_msg = str(error)
            if len(error_msg) > 0:
                if len(message) > 0:
                    message += '; '
                message += error_msg
        if message is not None and len(message) > 0:
            if error_code.value == ErrorCode.TRANSMISSION_UNKNOWN.value:
                if 'uthenticat' in message or 'uthoriz' in message:
                    error_code = ErrorCode.TRANSMISSION_AUTH_CREDENTIALS
                elif 'query_syntax_error' in message:
                    error_code = ErrorCode.TRANSMISSION_QUERY_PARSING_ERROR
            return_object['error'] = str(message)
        ErrorMapperBase.set_error_code(return_object, error_code.value)
        if error_code == ErrorCode.TRANSMISSION_UNKNOWN:
            ErrorResponder.call_module_error_mapper(message_struct, return_object)

    @staticmethod
    def call_module_error_mapper(json_data, return_object):
        caller_path_list = traceback.extract_stack()[-3].filename.split('/')
        caller_module_name = caller_path_list[-2]
        path_start_position = ErrorResponder.rindex(caller_path_list, 'stix_shifter')
        module_path = '.'.join(caller_path_list[path_start_position:-1]) + '.' + caller_module_name + '_error_mapper'
        try:
            module = importlib.import_module(module_path)
            if json_data is not None:
                module.ErrorMapper.set_error_code(json_data, return_object)
            else:
                ErrorMapperBase.set_error_code(return_object, module.ErrorMapper.DEFAULT_ERROR)
        except ModuleNotFoundError:
            pass

    @staticmethod
    def rindex(mylist, myvalue):
        return len(mylist) - mylist[::-1].index(myvalue) - 1

    @staticmethod
    def is_plain_string(s):
        return isinstance(s, str) and (not s.startswith('<?')) and (not s.startswith('{'))

    @staticmethod
    def is_json_string(s):
        return isinstance(s, str) and s.startswith('{')

import logging
import traceback

class ErrorResponder:

    @staticmethod
    def get_struct_item(message_struct, message_path):
        if message_struct is not None and message_path is not None:
            if isinstance(message_struct, collections.Mapping) or type(message_struct).__name__ == 'list':
                struct = message_struct.copy()
                for i in message_path:
                    if isinstance(struct, collections.Mapping) and i in struct or (type(struct).__name__ == 'list' and isinstance(i, int) and (i < len(struct))):
                        struct = struct[i]
                        if struct is None:
                            break
                    elif i[:1] == '+' and isinstance(struct, list):
                        (key, value) = i[1:].split('=')
                        filtered_struct = list(filter(lambda item: key in item and str(item[key]) == str(value), struct))
                        struct = filtered_struct
                    elif i[:1] == '~' and isinstance(struct, list):
                        key = i[1:]
                        filtered_struct = set()
                        for s in struct:
                            filtered_struct.add(s[key])
                        struct = list(filtered_struct)
                    else:
                        break
                return struct
            else:
                return message_struct

    @staticmethod
    def fill_error(return_object, message_struct=None, message_path=None, message=None, error=None):
        return_object['success'] = False
        error_code = ErrorCode.TRANSMISSION_UNKNOWN
        if message is None:
            message = ''
        struct_item = ErrorResponder.get_struct_item(message_struct, message_path)
        if struct_item is not None:
            if len(message) > 0:
                message += ';'
            if isinstance(struct_item, list):
                struct_item = json.dumps(struct_item)
            message += str(struct_item)
        error_msg = ''
        if error is not None:
            str_error = str(error)
            logging.error('Error occurred: %s\nStack trace: %s', str_error, traceback.format_exc())
            if isinstance(error, SSLError):
                error_code = ErrorCode.TRANSMISSION_AUTH_SSL
                error_msg = 'Wrong certificate: ' + str_error
            elif isinstance(error, ConnectionError):
                error_code = ErrorCode.TRANSMISSION_CONNECT
                error_msg = 'Connection error: ' + str_error
            else:
                error_msg = str(error)
            if len(error_msg) > 0:
                if len(message) > 0:
                    message += '; '
                message += error_msg
        if message is not None and len(message) > 0:
            if error_code.value == ErrorCode.TRANSMISSION_UNKNOWN.value:
                if 'uthenticat' in message or 'uthoriz' in message:
                    error_code = ErrorCode.TRANSMISSION_AUTH_CREDENTIALS
                elif 'query_syntax_error' in message:
                    error_code = ErrorCode.TRANSMISSION_QUERY_PARSING_ERROR
            return_object['error'] = str(message)
        ErrorMapperBase.set_error_code(return_object, error_code.value)
        if error_code == ErrorCode.TRANSMISSION_UNKNOWN:
            ErrorResponder.call_module_error_mapper(message_struct, return_object)

    @staticmethod
    def call_module_error_mapper(json_data, return_object):
        caller_path_list = traceback.extract_stack()[-3].filename.split('/')
        caller_module_name = caller_path_list[-2]
        path_start_position = ErrorResponder.rindex(caller_path_list, 'stix_shifter')
        module_path = '.'.join(caller_path_list[path_start_position:-1]) + '.' + caller_module_name + '_error_mapper'
        try:
            module = importlib.import_module(module_path)
            if json_data is not None:
                module.ErrorMapper.set_error_code(json_data, return_object)
            else:
                ErrorMapperBase.set_error_code(return_object, module.ErrorMapper.DEFAULT_ERROR)
        except ModuleNotFoundError:
            pass

    @staticmethod
    def rindex(mylist, myvalue):
        return len(mylist) - mylist[::-1].index(myvalue) - 1

    @staticmethod
    def is_plain_string(s):
        return isinstance(s, str) and (not s.startswith('<?')) and (not s.startswith('{'))

    @staticmethod
    def is_json_string(s):
        return isinstance(s, str) and s.startswith('{')

def setup_libunwind_env(qemu: boot_cheribsd.CheriBSDInstance, _: argparse.Namespace):
    if qemu.xtarget.is_cheri_purecap():
        lib_path = '/sysroot/usr/libcheri/'
    else:
        lib_path = '/sysroot/usr/lib/'
    qemu.checked_run(f'ln -sfv /build/lib/libunwind.so* /usr/lib/')
    qemu.checked_run(f'ln -sfv {lib_path}libcxxrt.so* {lib_path}libdl.so* /usr/lib/')
    qemu.checked_run('ln -sfv /usr/lib/libunwind.so /usr/lib/libgcc_s.so.1')

def colless_index(self):
    if self.num_roots != 1:
        raise ValueError('Colless index not defined for multiroot trees')
    num_leaves = np.zeros(self.tree_sequence.num_nodes, dtype=np.int32)
    total = 0
    for u in self.nodes(order='postorder'):
        num_children = 0
        for v in self.children(u):
            num_leaves[u] += num_leaves[v]
            num_children += 1
        if num_children == 0:
            num_leaves[u] = 1
        elif num_children != 2:
            raise ValueError('Colless index not defined for nonbinary trees')
        else:
            total += abs(num_leaves[self.right_child(u)] - num_leaves[self.left_child(u)])
    return total

def GetFormattedEvent(cls, event, event_data, event_tag):
    date_time = dfdatetime_posix_time.PosixTimeInMicroseconds(timestamp=event.timestamp)
    date_time_string = date_time.CopyToDateTimeStringISO8601()
    lines_of_text = ['+-' * 40, '[Timestamp]:', '  {0:s}'.format(date_time_string)]
    pathspec = getattr(event_data, 'pathspec', None)
    if pathspec:
        lines_of_text.extend(['', '[Pathspec]:'])
        lines_of_text.extend(['  {0:s}'.format(line) for line in pathspec.comparable.split('\n')])
        lines_of_text.pop()
    reserved_attributes = ['', '[Reserved attributes]:']
    additional_attributes = ['', '[Additional attributes]:']
    for (attribute_name, attribute_value) in sorted(event_data.GetAttributes()):
        if isinstance(attribute_value, py2to3.BYTES_TYPE) and attribute_value == b'':
            logging.debug('attribute: {0:s} of data type: {1:s} contains an empty bytes value'.format(attribute_name, event_data.data_type))
            attribute_value = None
        if attribute_name == 'pathspec':
            continue
        attribute_string = '  {{{0!s}}} {1!s}'.format(attribute_name, attribute_value)
        if attribute_name in definitions.RESERVED_VARIABLE_NAMES:
            reserved_attributes.append(attribute_string)
        else:
            additional_attributes.append(attribute_string)
    lines_of_text.extend(reserved_attributes)
    lines_of_text.extend(additional_attributes)
    if event_tag:
        labels = ["'{0:s}'".format(label) for label in event_tag.labels]
        lines_of_text.extend(['', '[Tag]:', '  {{labels}} [{0:s}]'.format(', '.join(labels))])
    lines_of_text.extend(['', ''])
    return '\n'.join(lines_of_text)

def post(self, request, *args, **kwargs):
    taskname = self.get_object()
    tasks = Task.objects.filter(Q(taskname=taskname) & ~Q(taskstatus_done_id)).order_by('task_id')
    task_ids = []
    for task in tasks:
        if task.task_started_time is None:
            task.task_started_time = timezone.now()
        task.task_finished_time = timezone.now()
        task.taskstatus = Taskstatus.objects.get(taskstatus_name='Done')
        task.save()
        task.logger(str(request.user), ' TASK_FINISH_EXECUTED')
        task_ids.append(task.task_id)
    taskname.logger(str(request.user), ' TASKNAME_CLOSE_EXECUTED')
    if tasks:
        messages.success(request, 'Closed task IDs: {}'.format(task_ids))
    else:
        messages.warning(request, 'No tasks to close.')
    return render(request, self.template_name, {'taskname': taskname, 'show_button': False})

def sendMessage(self, message):
    message = text(message)
    try:
        (command, data) = json.loads(message)
    except ValueError:
        if message.endswith('\x00'):
            message = message[:-1]
        (command, data) = json.loads(message)
    self.protocol.sendMessage({'_command': command, '_data': data})
    if command == 'mutation':
        self.protocol.sendMessage(metadata(self.protocol))

def parse_html5(raw, decoder=None, log=None, discard_namespaces=False, line_numbers=True, linenumber_attribute=None, replace_entities=True, fix_newlines=True):
    if isinstance(raw, bytes):
        raw = xml_to_unicode(raw)[0] if decoder is None else decoder(raw)
    if replace_entities:
        raw = xml_replace_entities(raw)
    if fix_newlines:
        raw = raw.replace('\r\n', '\n').replace('\r', '\n')
    raw = replace_chars.sub('', raw)
    stream_class = partial(FastStream, track_position=line_numbers)
    stream = stream_class(raw)
    builder = partial(NoNamespaceTreeBuilder if discard_namespaces else TreeBuilder, linenumber_attribute=linenumber_attribute)
    while True:
        try:
            parser = HTMLParser(tree=builder, track_positions=line_numbers, namespaceHTMLElements=not discard_namespaces)
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', category=DataLossWarning)
                try:
                    parser.parse(stream, parseMeta=False, useChardet=False)
                finally:
                    parser.tree.proxy_cache = None
        except NamespacedHTMLPresent as err:
            raw = re.sub('<\\s*/{0,1}(%s:)' % err.prefix, lambda m: m.group().replace(m.group(1), ''), raw, flags=re.I)
            stream = stream_class(raw)
            continue
        break
    root = parser.tree.getDocument()
    if discard_namespaces and root.tag != 'html' or (not discard_namespaces and (root.tag != '{%s}%s' % (namespaces['html'], 'html') or root.prefix)):
        raise ValueError('Failed to parse correctly, root has tag: %s and prefix: %s' % (root.tag, root.prefix))
    return root

class HTMLParser:

    def parse(self, stream, parseMeta=True, useChardet=True):
        pass

def parse_html5(raw, decoder=None, log=None, discard_namespaces=False, line_numbers=True, linenumber_attribute=None, replace_entities=True, fix_newlines=True):
    if isinstance(raw, bytes):
        raw = xml_to_unicode(raw)[0] if decoder is None else decoder(raw)
    raw = re.sub(r'<!\[CDATA\[(.*?)\]\]>', r'<![CDATA[
\1
]]>', raw)
    if replace_entities:
        raw = xml_replace_entities(raw)
    if fix_newlines:
        raw = raw.replace('\r\n', '\n').replace('\r', '\n')
    raw = replace_chars.sub('', raw)
    stream_class = partial(FastStream, track_position=line_numbers)
    stream = stream_class(raw)
    builder = partial(NoNamespaceTreeBuilder if discard_namespaces else TreeBuilder, linenumber_attribute=linenumber_attribute)
    while True:
        try:
            parser = HTMLParser(tree=builder, track_positions=line_numbers, namespaceHTMLElements=not discard_namespaces)
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', category=DataLossWarning)
                try:
                    parser.parse(stream, parseMeta=False, useChardet=False)
                finally:
                    parser.tree.proxy_cache = None
        except NamespacedHTMLPresent as err:
            raw = re.sub(r'<\s*/{0,1}(%s:)' % err.prefix, lambda m: m.group().replace(m.group(1), ''), raw, flags=re.I)
            stream = stream_class(raw)
            continue
        break
    root = parser.tree.getDocument()
    if (discard_namespaces and root.tag != 'html') or (
        not discard_namespaces and (root.tag != '{%s}%s' % (namespaces['html'], 'html') or root.prefix)):
        raise ValueError('Failed to parse correctly, root has tag: %s and prefix: %s' % (root.tag, root.prefix))
    return root

from typing import List
import os
import tensorflow as tf

def list_info_files(dir_path: str) -> List[str]:
    allowed_extensions = {'.txt', '.csv', '.json'}
    return [fname for fname in tf.io.gfile.listdir(dir_path) if not tf.io.gfile.isdir(os.path.join(dir_path, fname)) and any((fname.endswith(ext) for ext in allowed_extensions))]

import numpy as np
from astropy.nddata import StdDevUncertainty

def _set_uncertainty(err_array, err_type):
    if err_type == 'ivar':
        uncertainty = StdDevUncertainty(np.sqrt(1.0 / err_array))
    else:
        uncertainty = StdDevUncertainty(err_array)
    return uncertainty

