def _covering_set_of_owners_for(self, files):
    every_owner = set()
    covered_files = set()
    owners_options = []
    owner_to_files = {}
    for f in files:
        dirname = self.os_path.dirname(f)
        while dirname in self.owners_for:
            for owner in self.owners_for[dirname]:
                if owner not in owner_to_files:
                    owner_to_files[owner] = set()
                owner_to_files[owner].add(f)
            if self._stop_looking(dirname):
                break
            dirname = self.os_path.dirname(dirname)
    while covered_files != set(files):
        best_owner = None
        best_coverage = 0
        for (owner, covered) in owner_to_files.items():
            coverage = len(covered - covered_files)
            if coverage > best_coverage:
                best_coverage = coverage
                best_owner = owner
        if best_owner is None:
            break
        every_owner.add(best_owner)
        covered_files.update(owner_to_files[best_owner])
        owners_options.append(every_owner.copy())
    return owners_options

def _covering_set_of_owners_for(self, files):
    every_owner = set()
    owner_count = {}
    for f in files:
        dirname = self.os_path.dirname(f)
        while dirname in self.owners_for:
            for owner in self.owners_for[dirname]:
                if owner not in owner_count:
                    owner_count[owner] = 0
                owner_count[owner] += 1
            if self._stop_looking(dirname):
                break
            dirname = self.os_path.dirname(dirname)
    sorted_owners = sorted(owner_count.keys(), key=lambda o: owner_count[o], reverse=True)
    covered_files = set()
    for owner in sorted_owners:
        if len(covered_files) == len(files):
            break
        every_owner.add(owner)
        for f in files:
            if f not in covered_files and owner in self.owners_for.get(self.os_path.dirname(f), []):
                covered_files.add(f)
    return every_owner

def object_by_uid(self, uid, comp_filter=None):
    data = cdav.CalendarData()
    prop = dav.Prop() + data
    query = cdav.TextMatch(uid)
    query = cdav.PropFilter('UID') + query
    if comp_filter:
        query = comp_filter + query
    vcalendar = cdav.CompFilter('VCALENDAR') + query
    filter = cdav.Filter() + vcalendar
    root = cdav.CalendarQuery() + [prop, filter]
    response = self._query(root, 1, 'report')
    if response.status == 404:
        raise error.NotFoundError(errmsg(response))
    elif response.status == 400:
        raise error.ReportError(errmsg(response))
    items_found = response.tree.findall('.//' + dav.Response.tag)
    for r in items_found:
        href = unquote(r.find('.//' + dav.Href.tag).text)
        data = unquote(r.find('.//' + cdav.CalendarData.tag).text)
        data = self._unfold_content(data)
        if not f'\nUID:{uid}\n' in data:
            continue
        return self._calendar_comp_class_by_data(data)(self.client, url=URL.objectify(href), data=data, parent=self)
    raise error.NotFoundError(errmsg(response))

def _unfold_content(self, data):
    lines = data.split('\n')
    unfolded = []
    current_line = ''
    for line in lines:
        if line.startswith(' '):
            current_line += line.strip()
        else:
            if current_line:
                unfolded.append(current_line)
            current_line = line
    if current_line:
        unfolded.append(current_line)
    return '\n'.join(unfolded)

def has_perms(self):
    group_perms = get_groups_with_perms(self, attach_perms=True)
    for perms in group_perms.values():
        for perm in perms:
            if perm != self.add_permission_name:
                return True
    return False

def dispatch_commands(protocol_data, loaded_pipettes, loaded_labware):
    subprocedures = [p.get('subprocedure', []) for p in protocol_data.get('procedure', [])]
    default_values = protocol_data.get('default-values', {})
    flat_subs = chain.from_iterable(subprocedures)
    for command_item in flat_subs:
        command_type = command_item.get('command')
        params = command_item.get('params', {})
        pipette = _get_pipette(params, loaded_pipettes)
        pipette_model = protocol_data.get('pipettes', {}).get(params.get('pipette'), {}).get('model')
        location = _get_location(loaded_labware, command_type, params, default_values)
        volume = params.get('volume')
        if pipette:
            _set_flow_rate(pipette_model, pipette, command_type, params, default_values)
        if command_type == 'delay':
            wait = params.get('wait')
            if wait is None:
                raise ValueError('Delay cannot be null')
            elif wait is True:
                message = params.get('message', 'Pausing until user resumes')
                robot.comment(message)
                robot.pause()
            else:
                _sleep(wait)
        elif command_type == 'blowout':
            pipette.blow_out(location)
        elif command_type == 'pick-up-tip':
            pipette.pick_up_tip(location)
        elif command_type == 'drop-tip':
            pipette.drop_tip(location)
        elif command_type == 'aspirate':
            pipette.aspirate(volume, location)
        elif command_type == 'dispense':
            pipette.dispense(volume, location)
        elif command_type == 'touch-tip':
            pipette.touch_tip(location)

def _log_args(self, variables):
    args = ['${%s}' % arg for arg in self.arguments.positional]
    if self.arguments.varargs:
        args.append('@{%s}' % self.arguments.varargs)
    args = ['%s=%s' % (name, utils.safe_repr(variables[name])) for name in args]
    kwargs = ['%s=%s' % (key, utils.safe_repr(value)) for (key, value) in variables.items() if key not in self.arguments.positional]
    return 'Arguments: [ %s | %s ]' % (' | '.join(args), ' | '.join(kwargs))

import understand
import pandas as pd

class Modularity:

    def __init__(self, graph_path, db, **kwargs):
        self.mdg_df = pd.read_csv(graph_path)
        self.mdg_graph = nx.from_pandas_edgelist(self.mdg_df, source='From Class', target='To Class', edge_attr='References', create_using=nx.DiGraph())
        self.db = db

    def export_class_dependencies_to_csv(self, output_path):
        entities = self.db.ents('Java Class')
        dependencies = []
        for entity in entities:
            class_name = entity.longname()
            dependencies.append({'Class': class_name, 'Dependencies': entity.relations('Depends On')})
        df = pd.DataFrame(dependencies)
        df.to_csv(output_path, index=False)

    def compute_modularity_newman_leicht(self):
        q = 0
        if self.mdg_graph is not None and self.mdg_graph.number_of_edges() > 0:
            communities = self.__roster_communities()
            q = nx_comm.modularity(self.mdg_graph, communities=communities.values())
        return q

    def __roster_communities(self):
        communities_dict = dict()
        for node_ in self.mdg_graph:
            package_name = self.__get_package_name_by_understand_query(node_)
            if package_name in communities_dict.keys():
                communities_dict[package_name].append(node_)
            else:
                communities_dict[package_name] = [node_]
        return communities_dict

    def __get_package_name_by_understand_query(self, class_longname: str=None):
        (package_entity, package_longname) = UnderstandUtility.get_package_of_given_class_2(self.db, class_longname)
        return package_longname

