                check_infos[check_plugin_name]['group'] = check['group']
            check_infos[check_plugin_name]['service_description'] = check.get('service_description', '%s')
            check_infos[check_plugin_name]['snmp'] = cmk.base.check_utils.is_snmp_check(check_plugin_name)
        except Exception as e:
            if cmk.utils.debug.enabled():
                raise
            raise MKAutomationError("Failed to parse man page '%s': %s" % (check_plugin_name, e))
    return check_infos

def __repr__(self):
    try:
        query_result = self._build_query()
        results = self.execute()
        result_count = len(results)
        time_taken = '1ms'
        return '<Select {0}, {1} results, {2}>'.format(repr(query_result), result_count, time_taken)
    except RuntimeError:
        return repr(self._filters)

def __repr__(self):
    try:
        result_count = self.total()
        execution_time = '1ms'
        return '<Select {0}, {1} results, {2}>'.format(repr(self._build_query()), result_count, execution_time)
    except RuntimeError:
        return repr(self._filters)

def compile(self):
    self.reset_router()
    for (_, method_tuple) in self.methods.items():
        (method, method_config) = method_tuple
        self.router.add_method_handler(method_call=method, method_config=method_config)
    (self.approval_program, self.clear_program, self.contract) = self.router.compile_program(version=self.teal_version, assemble_constants=True, optimize=OptimizeOptions(scratch_slots=True))

def reset_router(self):
    self.router = Router(name=self.__class__.__name__, bare_calls=BareCallActions(**self.bare_externals), descr=self.__doc__)

def compile(self):
    self.router = Router(name=self.__class__.__name__, bare_calls=BareCallActions(**self.bare_externals), descr=self.__doc__)
    for (_, method_tuple) in self.methods.items():
        (method, method_config) = method_tuple
        self.router.add_method_handler(method_call=method, method_config=method_config)
    (self.approval_program, self.clear_program, self.contract) = self.router.compile_program(version=self.teal_version, assemble_constants=True, optimize=OptimizeOptions(scratch_slots=True))

def __call__(self, *args, **kwargs):
    default_height = 512
    default_width = 512
    height = kwargs.get('height', default_height)
    width = kwargs.get('width', default_width)
    if 'image' in kwargs:
        image = kwargs['image']
        if image.height != height or image.width != width:
            image = image.resize((width, height))
            kwargs['image'] = image
    return StableDiffusionImg2ImgPipelineMixin.__call__(self, *args, **kwargs)

def select(cls, clause=None, having=None, connection=None, order_by=None, distinct=None):
    (attributes, columns) = zip(*cls.columns.items())
    if connection is None:
        from stoqlib.database.runtime import get_connection
        connection = get_connection()
    store = connection.store
    clauses = []
    if clause:
        clauses.append(clause)
    if cls.clause:
        clauses.append(cls.clause)
    if clauses:
        clauses = [AND(*clauses)]
    tables = cls._get_tables_for_query(cls.tables[:], clause)

    def _load_view_objects(result, values):
        instance = cls()
        instance._connection = connection
        for (attribute, value) in zip(attributes, values):
            if hasattr(cls.columns[attribute], 'variable_factory'):
                var = cls.columns[attribute].variable_factory.func()
                if value is not None:
                    value = var.parse_set(value, False)
            setattr(instance, attribute, value)
        return instance
    results = store.using(*tables).find(columns, *clauses)
    if cls.group_by:
        results = results.group_by(*cls.group_by)
    if order_by:
        results = results.order_by(order_by)
    if distinct:
        results.config(distinct=True)
    results._load_objects = _load_view_objects
    results.orderBy = results.order_by
    return results

